const USE_FAKE_LOCATION = false;
const DEFAULT_MAP_REGION = {
  latitude: 40.7128,
  longitude: -74.006,
  latitudeDelta: 0.055,
  longitudeDelta: 0.045,
};
const DEMO_MAP_CENTER = {
  latitude: 41.7508,
  longitude: -88.1535,
};
const DEMO_MAP_REGION = {
  latitude: DEMO_MAP_CENTER.latitude,
  longitude: DEMO_MAP_CENTER.longitude,
  latitudeDelta: 0.055,
  longitudeDelta: 0.045,
};
const MAP_REGION = USE_FAKE_LOCATION ? DEMO_MAP_REGION : DEFAULT_MAP_REGION;
const MAP_REGION_EPSILON = 0.00003;
const createDemoCoordinate = (index = 0) => {
  const seed = Number.isFinite(index) ? index + 1 : 1;
  const angle = (seed * 137.5 * Math.PI) / 180;
  const radius = 0.003 + (seed % 6) * 0.0016;
  return {
    latitude: DEMO_MAP_CENTER.latitude + Math.sin(angle) * radius,
    longitude: DEMO_MAP_CENTER.longitude + Math.cos(angle) * radius,
  };
};

const createPrivacySafeServiceCoordinate = (coordinate) => {
  const latitude = Number(coordinate?.latitude);
  const longitude = Number(coordinate?.longitude);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;
  // Round the center to roughly a neighborhood block. The map renders a
  // broad service circle rather than an exact pin at this coordinate.
  return {
    latitude: Math.round(latitude * 1000) / 1000,
    longitude: Math.round(longitude * 1000) / 1000,
  };
};

const mapSupabaseBusiness = (row, index) => {
  const categoryKey = normalizeBusinessCategoryKey(
    row.category_key || row.category_label,
  );
  const categoryConfig = getCategoryConfig(categoryKey);
  const offerHighlight =
    typeof row.offer_highlight === "string" ? row.offer_highlight.trim() : "";
  const rawBusinessTags = Array.isArray(row.tags)
    ? row.tags.map((tag) => String(tag || "").trim()).filter(Boolean)
    : [];
  const inferredServiceAreaBusiness =
    rawBusinessTags.includes("__wello_service_area__") ||
    String(row.address || "").trim().toLowerCase() === "service-area business" ||
    (!String(row.postal_code || "").trim() &&
      Boolean(String(row.city || "").trim()) &&
      !/\d/.test(String(row.address || "")));
  const isShopAndMobileBusiness = rawBusinessTags.includes(
    "__wello_shop_and_mobile__",
  );
  const safeIndex = Number.isFinite(index) ? index : 0;
  const latitude = row.latitude !== null ? Number(row.latitude) : null;
  const longitude = row.longitude !== null ? Number(row.longitude) : null;
  const demoCoordinate = USE_FAKE_LOCATION
    ? createDemoCoordinate(safeIndex)
    : null;
  const hasCoordinates = USE_FAKE_LOCATION
    ? true
    : Number.isFinite(latitude) && Number.isFinite(longitude);
  const fallbackCoordinate = {
    latitude: MAP_REGION.latitude + safeIndex * 0.002,
    longitude: MAP_REGION.longitude - safeIndex * 0.002,
  };
  return {
    id: String(row.id || index + 1),
    ownerId: row.owner_id || null,
    name: row.name || "Wello business",
    address: row.address || "",
    category: categoryConfig.display,
    categoryLabel: categoryConfig.display,
    categoryKey,
    offer: offerHighlight,
    profileDescription: offerHighlight,
    distance: "--",
    rating: Number.isFinite(Number(row.rating)) ? Number(row.rating) : null,
    tags: sanitizeBusinessTags(rawBusinessTags),
    isServiceAreaBusiness: inferredServiceAreaBusiness,
    isShopAndMobileBusiness,
    isOpen: row.is_open ?? true,
    hours: row.hours || "Hours available upon request",
    phone: row.phone || "",
    merchantDescriptorAliases: Array.isArray(row.merchant_descriptor_aliases)
      ? row.merchant_descriptor_aliases.filter(Boolean)
      : [],
    city: row.city || "",
    state: row.state || "",
    postalCode: row.postal_code || "",
    imageUrl: String(row.image_url || "").trim() || "",
    coverImageUrl: String(row.image_url || "").trim() || "",
    createdAt: row.created_at ? new Date(row.created_at).getTime() : daysAgo(5),
    coordinate: USE_FAKE_LOCATION
      ? demoCoordinate
      : hasCoordinates
        ? { latitude, longitude }
        : null,
    fallbackCoordinate,
    hasCoordinates,
    approved: row.approval_status === "approved",
    rejected: row.approval_status === "rejected",
    status: row.status || "active",
    qrCode: row.qr_code || "",
    stripeAccountId: row.stripe_account_id || null,
    stripeCustomerId: row.stripe_customer_id || null,
    stripePaymentMethodId: row.stripe_payment_method_id || null,
    stripePaymentMethodBrand: row.stripe_payment_method_brand || null,
    stripePaymentMethodLast4: row.stripe_payment_method_last4 || null,
    stripeChargesEnabled: row.stripe_charges_enabled ?? false,
    stripePayoutsEnabled: row.stripe_payouts_enabled ?? false,
    stripeOnboardedAt: row.stripe_onboarded_at
      ? new Date(row.stripe_onboarded_at).getTime()
      : null,
    stripeOnboarded:
      row.stripe_onboarded ??
      Boolean(row.stripe_account_id && row.stripe_charges_enabled),
    stripeGated:
      row.stripe_gated ??
      Boolean(row.stripe_payment_method_id),
    commissionRateCents: normalizeBusinessCommissionRateCents(
      row.commission_rate_cents,
    ),
    defaultCashbackRateBps: resolveBusinessDefaultCashbackRateBps(
      row.commission_rate_cents,
      row.default_cashback_rate_bps,
    ),
    commissionEnabled: row.commission_enabled ?? true,
    source: "supabase",
  };
};

function ActiveBusinessBridge({
  onBusinessesChange,
  onActiveBusinessChange,
  controlsRef,
}) {
  const {
    activeBusiness,
    businesses,
    loading,
    loaded,
    error,
    refreshBusinesses,
    setActiveBusiness,
  } = useActiveBusiness();

  useEffect(() => {
    onBusinessesChange?.({
      businesses,
      loading,
      loaded,
      error,
    });
  }, [businesses, error, loaded, loading, onBusinessesChange]);

  useEffect(() => {
    onActiveBusinessChange?.(activeBusiness);
  }, [activeBusiness, onActiveBusinessChange]);

  useEffect(() => {
    if (!controlsRef) return undefined;
    controlsRef.current = {
      refreshBusinesses,
      setActiveBusiness,
      selectBusinessById: (businessId) => {
        const match = businesses.find((entry) => entry.id === businessId);
        if (match) {
          setActiveBusiness(match);
        }
      },
    };
    return () => {
      if (controlsRef.current) {
        controlsRef.current = null;
      }
    };
  }, [businesses, controlsRef, refreshBusinesses, setActiveBusiness]);

  return null;
}

const mapSupabaseOffer = (row) => ({
  id: String(row.id),
  businessId: row.business_id,
  title: row.title || "",
  description: "",
  offerType: "cashback",
  imageUrl: "",
  active: row.active ?? true,
  status: row.status || "active",
  startsAt: row.starts_at ? new Date(row.starts_at).getTime() : null,
  expiresAt: row.expires_at ? new Date(row.expires_at).getTime() : null,
  approvalStatus: row.approval_status || "approved",
  redemptionLimitPeriod: row.redemption_limit_period || null,
  redemptionLimitCount: Number.isFinite(Number(row.redemption_limit_count))
    ? Number(row.redemption_limit_count)
    : null,
  createdAt: row.created_at ? new Date(row.created_at).getTime() : Date.now(),
  business: row.business ? mapSupabaseBusiness(row.business, 0) : null,
});

const getManualPurchaseFromRedemption = (row) => {
  const submission = Array.isArray(row?.manual_purchase_submissions)
    ? row.manual_purchase_submissions[0]
    : row?.manual_purchase_submissions;
  if (submission) return submission;
  const payload = String(row?.qr_payload || "");
  if (!payload.startsWith("wello_manual_purchase:")) return null;
  try {
    return JSON.parse(payload.slice("wello_manual_purchase:".length));
  } catch {
    return null;
  }
};

const mapSupabaseRedemption = (row) => ({
  id: String(row.id),
  createdAt: row.created_at ? new Date(row.created_at).getTime() : Date.now(),
  businessId: row.business_id || null,
  offerId: row.offer_id || null,
  offer: row.offer || null,
  business: row.business || null,
  manualPurchase: (() => {
    const submission = getManualPurchaseFromRedemption(row);
    if (!submission) return null;
    return {
      id: String(submission.id),
      amountCents: Number(submission.amount_cents) || 0,
      paymentType: submission.payment_type || "other",
      paymentMethodDetail:
        String(submission.payment_method_detail || "").trim() || null,
      status: submission.status || "processing",
      createdAt: submission.created_at
        ? new Date(submission.created_at).getTime()
        : null,
      reviewedAt: submission.reviewed_at
        ? new Date(submission.reviewed_at).getTime()
        : null,
      reviewNotes: String(submission.review_notes || "").trim() || null,
    };
  })(),
  purchaseVerification: (() => {
    const verification = Array.isArray(row.purchase_verifications)
      ? row.purchase_verifications[0]
      : row.purchase_verifications;
    if (!verification) {
      const submission = getManualPurchaseFromRedemption(row);
      if (!submission) return null;
      const approved = ["approved", "paid"].includes(submission.status);
      const rejected = submission.status === "rejected";
      return {
        id: `manual-${submission.id}`,
        source: "manual",
        status: approved ? "confirmed" : rejected ? "rejected" : "pending",
        reasonCode: approved
          ? "manual_purchase_approved"
          : rejected
            ? "manual_purchase_rejected"
            : "manual_purchase_processing",
        reasonDetail: approved
          ? "Purchase approved."
          : rejected
            ? submission.review_notes || "Purchase was not approved."
            : "Processing until approved by Wello.",
        lastCheckedAt: submission.reviewed_at
          ? new Date(submission.reviewed_at).getTime()
          : new Date(submission.created_at).getTime(),
        confirmedAt: approved && submission.reviewed_at
          ? new Date(submission.reviewed_at).getTime()
          : null,
        rejectedAt: rejected && submission.reviewed_at
          ? new Date(submission.reviewed_at).getTime()
          : null,
      };
    }
    return {
      id: String(verification.id),
      source: verification.source || null,
      status: verification.status || null,
      reasonCode: verification.reason_code || null,
      reasonDetail: verification.reason_detail || null,
      lastCheckedAt: verification.last_checked_at
        ? new Date(verification.last_checked_at).getTime()
        : null,
      confirmedAt: verification.confirmed_at
        ? new Date(verification.confirmed_at).getTime()
        : null,
      rejectedAt: verification.rejected_at
        ? new Date(verification.rejected_at).getTime()
        : null,
    };
  })(),
  receipt: (() => {
    const receipt = Array.isArray(row.receipt_uploads)
      ? row.receipt_uploads[0]
      : row.receipt_uploads;
    if (!receipt) {
      if (String(row?.qr_payload || "") !== "checkout_receipt_submitted") {
        return null;
      }
      return {
        id: `submitted-${row.id}`,
        storagePath: "",
        verificationSource: "receipt",
        verificationReference: null,
        reviewStatus: "pending",
        retryAllowed: false,
        reviewNotes: null,
        uploadedAt: row.created_at
          ? new Date(row.created_at).getTime()
          : Date.now(),
        cashbackCents: 0,
        cashbackStatus: null,
      };
    }
    const cashbackEvent = (() => {
      const events = Array.isArray(receipt.cashback_events)
        ? receipt.cashback_events
        : receipt.cashback_events
          ? [receipt.cashback_events]
          : [];
      return events[0] || null;
    })();
    return {
      id: String(receipt.id),
      storagePath: receipt.storage_path || "",
      verificationSource: receipt.verification_source || "receipt",
      verificationReference: receipt.verification_reference || null,
      reviewStatus: receipt.review_status || null,
      retryAllowed: receipt.retry_allowed === true,
      reviewNotes: String(receipt.review_notes || "").trim() || null,
      uploadedAt: receipt.uploaded_at
        ? new Date(receipt.uploaded_at).getTime()
        : Date.now(),
      cashbackCents: Number(cashbackEvent?.amount_cents) || 0,
      cashbackStatus: cashbackEvent?.status || null,
    };
  })(),
});

