const mapSupabaseReview = (row) => ({
  id: String(row.id),
  businessId: row.business_id || null,
  redemptionId: row.redemption_id || null,
  offerId: row.offer_id || null,
  rating: Number(row.rating) || 0,
  reviewText: row.review_text || "",
  createdAt: row.created_at ? new Date(row.created_at).getTime() : Date.now(),
});

const computeAverageRating = (reviews) => {
  const values = (reviews || [])
    .map((review) => Number(review.rating))
    .filter((rating) => Number.isFinite(rating) && rating > 0);
  if (!values.length) return null;
  return values.reduce((sum, rating) => sum + rating, 0) / values.length;
};

const formatDisplayName = (email) => {
  if (!email) return "Wello Member";
  const fallbackName = email.split("@")[0] || "Wello Member";
  return fallbackName
    .replace(/[._-]+/g, " ")
    .split(" ")
    .map((part) => part.slice(0, 1).toUpperCase() + part.slice(1))
    .join(" ");
};

const isGoogleAuthUser = (user) => {
  if (!user) return false;
  const appProvider = String(user?.app_metadata?.provider || "")
    .trim()
    .toLowerCase();
  if (appProvider === "google") return true;
  const identities = Array.isArray(user?.identities) ? user.identities : [];
  return identities.some((identity) => {
    const provider = String(
      identity?.provider || identity?.identity_data?.provider || "",
    )
      .trim()
      .toLowerCase();
    return provider === "google";
  });
};

const normalizePhoneDigits = (value) => String(value || "").replace(/\D/g, "");

const isValidBusinessPhoneNumber = (value) => {
  const digits = normalizePhoneDigits(value);
  if (digits.length === 10) return true;
  return digits.length === 11 && digits.startsWith("1");
};

const splitFullName = (value) => {
  const normalized = String(value || "")
    .trim()
    .replace(/\s+/g, " ");
  if (!normalized) {
    return { firstName: "", lastName: "" };
  }
  const parts = normalized.split(" ");
  return {
    firstName: parts[0] || "",
    lastName: parts.slice(1).join(" "),
  };
};

const joinFullNameParts = (firstName, lastName) =>
  [String(firstName || "").trim(), String(lastName || "").trim()]
    .filter(Boolean)
    .join(" ");

const formatHistoryTimestamp = (value) => {
  if (!value) return "Date unavailable";
  const date = new Date(value);
  const dateLabel = date.toLocaleDateString();
  const timeLabel = date.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });
  return `${dateLabel} - ${timeLabel}`;
};

const formatReceiptUploadCountdown = (redeemedAt, now = Date.now()) => {
  if (!redeemedAt) return null;
  const remainingMs =
    Number(redeemedAt) + RECEIPT_UPLOAD_WINDOW_MS - Number(now);
  if (!Number.isFinite(remainingMs) || remainingMs <= 0) {
    return "Upload window closed";
  }
  const totalMinutes = Math.max(1, Math.ceil(remainingMs / (1000 * 60)));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (hours <= 0) return `${minutes}m left`;
  if (minutes === 0) return `${hours}h left`;
  return `${hours}h ${minutes}m left`;
};

const hexToRgba = (hex, alpha) => {
  const raw = String(hex || "")
    .replace("#", "")
    .trim();
  const normalized =
    raw.length === 3
      ? raw
          .split("")
          .map((c) => c + c)
          .join("")
      : raw;
  if (normalized.length !== 6) return `rgba(15, 23, 42, ${alpha})`;
  const r = parseInt(normalized.slice(0, 2), 16);
  const g = parseInt(normalized.slice(2, 4), 16);
  const b = parseInt(normalized.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
};

const getInitials = (value) => {
  const name = String(value || "").trim();
  if (!name) return "W";
  const parts = name
    .replace(/[^\w\s]/g, " ")
    .split(/\s+/)
    .filter(Boolean);
  if (!parts.length) return "W";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0].slice(0, 1) + parts[1].slice(0, 1)).toUpperCase();
};

const HISTORY_GROUP_AVATAR_COLORS = [
  "#FF7A00",
  "#F4A300",
  "#F43F5E",
  "#EF4444",
  "#22C55E",
  "#0EA5E9",
  "#8B5CF6",
];
const CASHOUT_BANK_AVATAR_COLORS = [
  "#1F7DD0",
  "#CF1D37",
  "#6D5EF3",
  "#0F9D7A",
  "#C87014",
  "#0F5DA8",
];

const getHistoryGroupAvatarColor = (value) => {
  const seed = String(value || "").trim();
  if (!seed) return HISTORY_GROUP_AVATAR_COLORS[0];
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  return HISTORY_GROUP_AVATAR_COLORS[hash % HISTORY_GROUP_AVATAR_COLORS.length];
};

const formatOfferDate = (value) => {
  if (!value) return "Date unavailable";
  const date = new Date(value);
  return date.toLocaleDateString();
};

const formatOfferRedemptionLimit = (period, count) => {
  const normalizedPeriod = String(period || "")
    .trim()
    .toLowerCase();
  const normalizedCount = Math.floor(Number(count));
  const hasLimit =
    Number.isFinite(normalizedCount) &&
    normalizedCount > 0 &&
    (normalizedPeriod === "day" || normalizedPeriod === "week");
  if (!hasLimit) return "Unlimited per customer";
  const unit = normalizedPeriod === "week" ? "week" : "day";
  const cadence = unit === "week" ? "rolling 7 days" : "rolling 24 hours";
  return `${normalizedCount} per ${unit} (${cadence})`;
};

const formatShortDate = (value) => {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
  });
};

const maskRecoveryEmail = (value) => {
  const email = String(value || "").trim();
  if (!email.includes("@")) return "--";
  const [localPart, domain] = email.split("@");
  const localTrimmed = String(localPart || "").trim();
  if (!localTrimmed) return `***@${domain}`;
  if (localTrimmed.length <= 2) return `${localTrimmed[0] || "*"}***@${domain}`;
  return `${localTrimmed.slice(0, 2)}***@${domain}`;
};

const maskRecoveryPhone = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "--";
  const digits = raw.replace(/\D/g, "");
  if (digits.length < 4) return "***";
  return `***-***-${digits.slice(-4)}`;
};

const formatReceiptTime = (value) => {
  if (!value) return "--";
  return new Date(value).toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });
};

const formatPurchaseVerificationReason = (reasonCode, reasonDetail) => {
  if (reasonDetail) return reasonDetail;
  switch (String(reasonCode || "").trim()) {
    case "bank_not_linked":
      return "Link your bank for instant verification, or upload a receipt.";
    case "transaction_pending":
      return "Matching transaction found but still pending settlement.";
    case "transaction_delayed":
      return "Transaction data is delayed. Upload a receipt if needed now.";
    case "merchant_mismatch":
      return "Merchant details could not be matched confidently.";
    case "amount_mismatch":
      return "Amount could not be matched confidently.";
    case "identity_mismatch":
      return "Account ownership check did not match.";
    case "receipt_under_review":
      return "Receipt sent for review.";
    case "receipt_rejected":
      return "Receipt review was rejected.";
    default:
      return "";
  }
};

const formatBusinessHours = (startTime, startMeridiem, endTime, endMeridiem) =>
  `${startTime} ${startMeridiem} - ${endTime} ${endMeridiem}`;

const minutesToTimeValue = (minutes) => {
  if (!Number.isFinite(minutes)) return "";
  const normalized = ((Math.round(minutes) % (24 * 60)) + 24 * 60) % (24 * 60);
  const hours = Math.floor(normalized / 60);
  const mins = normalized % 60;
  return `${String(hours).padStart(2, "0")}:${String(mins).padStart(2, "0")}`;
};

const parseTimeValueToMinutes = (value) => {
  const match = String(value || "").trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (
    !Number.isInteger(hours) ||
    !Number.isInteger(minutes) ||
    hours < 0 ||
    hours > 23 ||
    minutes < 0 ||
    minutes > 59
  ) {
    return null;
  }
  return hours * 60 + minutes;
};

const createDefaultBusinessHoursSchedule = () =>
  OPERATING_DAY_OPTIONS.map((day) => ({
    dayKey: day.key,
    open: true,
    start: "09:00",
    end: "17:00",
  }));

const cloneBusinessHoursSchedule = (schedule) =>
  OPERATING_DAY_OPTIONS.map((day) => {
    const entry = Array.isArray(schedule)
      ? schedule.find((item) => String(item?.dayKey || "") === day.key)
      : null;
    return {
      dayKey: day.key,
      open: entry?.open !== false,
      start: String(entry?.start || "09:00"),
      end: String(entry?.end || "17:00"),
    };
  });

const getBusinessHoursScheduleEntry = (schedule, dayKey) =>
  cloneBusinessHoursSchedule(schedule).find((entry) => entry.dayKey === dayKey) || {
    dayKey,
    open: false,
    start: "09:00",
    end: "17:00",
  };

const isBusinessHoursSchedule24Seven = (schedule) => {
  const entries = cloneBusinessHoursSchedule(schedule);
  return entries.every(
    (entry) =>
      entry.open &&
      Number.isFinite(parseTimeValueToMinutes(entry.start)) &&
      parseTimeValueToMinutes(entry.start) === parseTimeValueToMinutes(entry.end),
  );
};

const formatBusinessHoursScheduleForStorage = (schedule) =>
  cloneBusinessHoursSchedule(schedule)
    .map((entry) => {
      const dayLabel = OPERATING_DAY_FULL_LABEL[entry.dayKey] || entry.dayKey;
      if (!entry.open) return `${dayLabel}: Closed`;
      const startMinutes = parseTimeValueToMinutes(entry.start);
      const endMinutes = parseTimeValueToMinutes(entry.end);
      if (!Number.isFinite(startMinutes) || !Number.isFinite(endMinutes)) {
        return `${dayLabel}: Closed`;
      }
      return `${dayLabel}: ${formatClockLabelFromMinutes(startMinutes, false)} - ${formatClockLabelFromMinutes(endMinutes, false)}`;
    })
    .join("\n");

const parseBusinessHoursSchedule = (value) => {
  const raw = String(value || "").replace(/\r/g, "").trim();
  if (!raw) return null;

  const lines = raw
    .split(/\n|;/)
    .map((line) => line.trim())
    .filter(Boolean);

  const parsedSchedule = createDefaultBusinessHoursSchedule().map((entry) => ({
    ...entry,
    open: false,
  }));
  let matchedCount = 0;

  lines.forEach((line) => {
    const match = line.match(
      /^(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday|Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s*:\s*(Closed|(\d{1,2}:\d{2}\s*(?:AM|PM))\s*-\s*(\d{1,2}:\d{2}\s*(?:AM|PM)))$/i,
    );
    if (!match) return;
    const dayKey =
      OPERATING_DAY_OPTIONS[
        OPERATING_DAY_INDEX[String(match[1] || "").toLowerCase()] ?? -1
      ]?.key || "";
    if (!dayKey) return;
    const target = parsedSchedule.find((entry) => entry.dayKey === dayKey);
    if (!target) return;
    matchedCount += 1;
    const closed = String(match[2] || "").toLowerCase() === "closed";
    if (closed) {
      target.open = false;
      return;
    }
    const startPart = String(match[3] || "").trim();
    const endPart = String(match[4] || "").trim();
    const parseLegacyPart = (part) => {
      const partMatch = part.match(/^(\d{1,2}:\d{2})\s*(AM|PM)$/i);
      if (!partMatch) return null;
      return parseClockMinutes(partMatch[1], partMatch[2].toUpperCase());
    };
    const startMinutes = parseLegacyPart(startPart);
    const endMinutes = parseLegacyPart(endPart);
    if (!Number.isFinite(startMinutes) || !Number.isFinite(endMinutes)) {
      target.open = false;
      return;
    }
    target.open = true;
    target.start = minutesToTimeValue(startMinutes);
    target.end = minutesToTimeValue(endMinutes);
  });

  if (matchedCount > 0) {
    return parsedSchedule;
  }

  const parsedLegacy = parseBusinessHours(value);
  if (!parsedLegacy) return null;
  const selectedDays = new Set(parseOperatingDaysValue(parsedLegacy.days || ""));
  const startMinutes = parseClockMinutes(
    parsedLegacy.startTime,
    parsedLegacy.startMeridiem,
  );
  const endMinutes = parseClockMinutes(
    parsedLegacy.endTime,
    parsedLegacy.endMeridiem,
  );
  if (!Number.isFinite(startMinutes) || !Number.isFinite(endMinutes)) {
    return null;
  }
  return createDefaultBusinessHoursSchedule().map((entry) => ({
    ...entry,
    open: selectedDays.has(entry.dayKey),
    start: minutesToTimeValue(startMinutes),
    end: minutesToTimeValue(endMinutes),
  }));
};

const hasValidBusinessHoursSchedule = (schedule) =>
  cloneBusinessHoursSchedule(schedule).some((entry) => {
    if (!entry.open) return false;
    return (
      Number.isFinite(parseTimeValueToMinutes(entry.start)) &&
      Number.isFinite(parseTimeValueToMinutes(entry.end))
    );
  });

const getBusinessHoursTimeLabel = (value) =>
  OFFER_EXPIRY_TIME_OPTIONS.find((option) => option.value === String(value || "").trim())
    ?.label || "Select time";

const parseOperatingDaysValue = (value) => {
  const raw = String(value || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!raw) return OPERATING_DAY_OPTIONS.map((day) => day.key);

  const cleaned = raw.toLowerCase();
  if (cleaned === "daily" || cleaned === "every day" || cleaned === "mon-sun") {
    return OPERATING_DAY_OPTIONS.map((day) => day.key);
  }

  const selected = new Set();
  const normalized = raw.replace(/\s*-\s*/g, "-");
  const tokens = normalized
    .split(/[,/|]+/)
    .map((token) => token.trim())
    .filter(Boolean);

  const expandToken = (token) => {
    const rangeParts = token.split("-");
    if (rangeParts.length === 2) {
      const startIdx =
        OPERATING_DAY_INDEX[String(rangeParts[0] || "").toLowerCase()];
      const endIdx =
        OPERATING_DAY_INDEX[String(rangeParts[1] || "").toLowerCase()];
      if (startIdx == null || endIdx == null) return;
      if (startIdx <= endIdx) {
        for (let i = startIdx; i <= endIdx; i += 1) {
          selected.add(OPERATING_DAY_OPTIONS[i].key);
        }
      } else {
        for (let i = startIdx; i < OPERATING_DAY_OPTIONS.length; i += 1) {
          selected.add(OPERATING_DAY_OPTIONS[i].key);
        }
        for (let i = 0; i <= endIdx; i += 1) {
          selected.add(OPERATING_DAY_OPTIONS[i].key);
        }
      }
      return;
    }
    const exactIdx = OPERATING_DAY_INDEX[token.toLowerCase()];
    if (exactIdx != null) {
      selected.add(OPERATING_DAY_OPTIONS[exactIdx].key);
    }
  };

  tokens.forEach(expandToken);
  if (!selected.size) return OPERATING_DAY_OPTIONS.map((day) => day.key);

  return OPERATING_DAY_OPTIONS.map((day) => day.key).filter((key) =>
    selected.has(key),
  );
};

const formatOperatingDaysValue = (value) => {
  const ordered = parseOperatingDaysValue(value);
  if (ordered.length === OPERATING_DAY_OPTIONS.length) return "Mon-Sun";
  return ordered.join(", ");
};

const toggleOperatingDayValue = (value, dayKey) => {
  const current = new Set(parseOperatingDaysValue(value));
  if (current.has(dayKey)) {
    if (current.size === 1) return formatOperatingDaysValue(value);
    current.delete(dayKey);
  } else {
    current.add(dayKey);
  }
  const ordered = OPERATING_DAY_OPTIONS.map((day) => day.key).filter((key) =>
    current.has(key),
  );
  return formatOperatingDaysValue(ordered.join(", "));
};

const formatBusinessSchedule = (
  operatingDays,
  startTime,
  startMeridiem,
  endTime,
  endMeridiem,
) => {
  const timeRange = formatBusinessHours(
    startTime,
    startMeridiem,
    endTime,
    endMeridiem,
  );
  const days = formatOperatingDaysValue(operatingDays);
  return days ? `${days} | ${timeRange}` : timeRange;
};

const mergeVerificationCopy = (...parts) => {
  const unique = [];
  parts.forEach((part) => {
    const text = String(part || "").trim();
    if (!text) return;
    if (!unique.includes(text)) unique.push(text);
  });
  return unique.join("\n\n");
};

const isTransientProfileUpsertRls = (message) => {
  const text = String(message || "").toLowerCase();
  return (
    text.includes("row-level security policy") ||
    text.includes("violates row-level security policy") ||
    text.includes("permission denied")
  );
};

const parseBusinessHours = (value) => {
  if (!value) return null;
  const normalized = String(value)
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/\s+/g, " ")
    .trim();
  let days = "";
  let timePart = normalized;

  if (normalized.includes("·")) {
    const [daysPart, ...timeParts] = normalized.split("·");
    days = String(daysPart || "").trim();
    timePart = String(timeParts.join("·") || "").trim();
  } else if (normalized.includes("Â·")) {
    const [daysPart, ...timeParts] = normalized.split("Â·");
    days = String(daysPart || "").trim();
    timePart = String(timeParts.join("Â·") || "").trim();
  } else if (normalized.includes("|")) {
    const [daysPart, ...timeParts] = normalized.split("|");
    days = String(daysPart || "").trim();
    timePart = String(timeParts.join("|") || "").trim();
  } else {
    const looseMatch = normalized.match(
      /^(.+?)\s+(\d{1,2}(?::\d{2})?\s*(?:AM|PM)?\s*-\s*\d{1,2}(?::\d{2})?\s*(?:AM|PM)?)$/i,
    );
    if (looseMatch) {
      days = String(looseMatch[1] || "").trim();
      timePart = String(looseMatch[2] || "").trim();
    }
  }

  const parts = timePart
    .split("-")
    .map((part) => part.trim())
    .filter(Boolean);
  if (parts.length !== 2) return null;
  const parsePart = (part) => {
    const match = part.match(/^(\d{1,2}(?::\d{2})?)\s*(AM|PM)?$/i);
    if (!match) return null;
    return {
      time: match[1],
      meridiem: (match[2] || "AM").toUpperCase(),
    };
  };
  const start = parsePart(parts[0]);
  const end = parsePart(parts[1]);
  if (!start || !end) return null;
  return {
    days: formatOperatingDaysValue(days),
    startTime: start.time,
    startMeridiem: start.meridiem,
    endTime: end.time,
    endMeridiem: end.meridiem,
  };
};

const summarizeBusinessHoursValue = (value) => {
  const parsed = parseBusinessHours(value);
  const detailedSchedule = parseBusinessHoursSchedule(value);
  if (
    detailedSchedule &&
    isBusinessHoursSchedule24Seven(detailedSchedule)
  ) {
    return "Open 24/7";
  }
  if (Array.isArray(detailedSchedule) && detailedSchedule.length > 0) {
    const groups = [];
    detailedSchedule.forEach((entry) => {
      const startMinutes = parseTimeValueToMinutes(entry.start);
      const endMinutes = parseTimeValueToMinutes(entry.end);
      const valueKey =
        entry.open && Number.isFinite(startMinutes) && Number.isFinite(endMinutes)
          ? `${startMinutes}-${endMinutes}`
          : "closed";
      const previous = groups[groups.length - 1];
      if (previous?.valueKey === valueKey) {
        previous.endDay = entry.dayKey;
      } else {
        groups.push({
          startDay: entry.dayKey,
          endDay: entry.dayKey,
          valueKey,
          startMinutes,
          endMinutes,
        });
      }
    });
    return groups
      .map((group) => {
        const dayLabel =
          group.startDay === group.endDay
            ? group.startDay
            : `${group.startDay}-${group.endDay}`;
        if (group.valueKey === "closed") return `${dayLabel}: Closed`;
        return `${dayLabel}: ${formatClockLabelFromMinutes(group.startMinutes, false)} - ${formatClockLabelFromMinutes(group.endMinutes, false)}`;
      })
      .join("\n");
  }
  if (parsed) {
    const timeRange = formatBusinessHours(
      parsed.startTime,
      parsed.startMeridiem,
      parsed.endTime,
      parsed.endMeridiem,
    );
    return parsed.days ? `${parsed.days}: ${timeRange}` : timeRange;
  }
  const raw = String(value || "").trim();
  if (!raw) return "Hours vary";
  if (raw.includes("{") || raw.includes("[")) return "Hours vary";
  return raw;
};

const levenshteinDistance = (value, target) => {
  const a = String(value || "");
  const b = String(target || "");
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const rows = Array.from({ length: a.length + 1 }, () =>
    Array(b.length + 1).fill(0),
  );
  for (let i = 0; i <= a.length; i += 1) rows[i][0] = i;
  for (let j = 0; j <= b.length; j += 1) rows[0][j] = j;
  for (let i = 1; i <= a.length; i += 1) {
    for (let j = 1; j <= b.length; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      rows[i][j] = Math.min(
        rows[i - 1][j] + 1,
        rows[i][j - 1] + 1,
        rows[i - 1][j - 1] + cost,
      );
    }
  }
  return rows[a.length][b.length];
};

const OFFER_TYPE_LABELS = {
  bogo: "BOGO",
  cashback: "Cashback",
  discount: "Discount",
  bundle: "Bundle",
  freebie: "Freebie",
  event: "Event",
  happy_hour: "Happy Hour",
  limited_time: "Limited Time",
};

const OFFER_TYPE_OTHER_KEY = "__other__";
const OFFER_TYPE_DROPDOWN_OPTIONS = [
  { value: "Cashback", label: "Cashback" },
  { value: "Discount", label: "Discount" },
  { value: "BOGO", label: "BOGO" },
  { value: "Bundle", label: "Bundle" },
  { value: "Freebie", label: "Free item" },
  { value: "Event", label: "Event" },
  { value: "Happy Hour", label: "Happy hour" },
  { value: "Limited Time", label: "Limited time" },
  { value: OFFER_TYPE_OTHER_KEY, label: "Other" },
];

const normalizeOfferType = (input) => {
  const raw = String(input || "").trim();
  if (!raw) return "";
  const lower = raw.toLowerCase();
  const aliases = {
    "buy one get one": "bogo",
    buy1get1: "bogo",
    b1g1: "bogo",
    "2 for 1": "bogo",
    "2for1": "bogo",
    "two for one": "bogo",
    "two-for-one": "bogo",
    bogo: "bogo",
    cashback: "cashback",
    "cash back": "cashback",
    discount: "discount",
    "percent off": "discount",
    "percentage off": "discount",
    promo: "discount",
    bundle: "bundle",
    free: "freebie",
    freebie: "freebie",
    event: "event",
    "happy hour": "happy_hour",
    happyhour: "happy_hour",
    "limited time": "limited_time",
    limitedtime: "limited_time",
    lto: "limited_time",
  };
  if (aliases[lower]) return OFFER_TYPE_LABELS[aliases[lower]];
  const entries = Object.entries(OFFER_TYPE_LABELS);
  for (const [, label] of entries) {
    const labelLower = label.toLowerCase();
    if (labelLower.includes(lower) || lower.includes(labelLower)) {
      return label;
    }
  }
  let bestLabel = raw;
  let bestScore = Number.POSITIVE_INFINITY;
  entries.forEach(([key, label]) => {
    const labelLower = label.toLowerCase();
    const score = Math.min(
      levenshteinDistance(lower, key),
      levenshteinDistance(lower, labelLower),
    );
    if (score < bestScore) {
      bestScore = score;
      bestLabel = label;
    }
  });
  const threshold = Math.max(2, Math.floor(raw.length * 0.3));
  return bestScore <= threshold ? bestLabel : raw;
};

const normalizeOfferTypeSelection = (input) => {
  const normalized = normalizeOfferType(input);
  if (!normalized) return "";
  const preset = OFFER_TYPE_DROPDOWN_OPTIONS.find(
    (option) =>
      option.value !== OFFER_TYPE_OTHER_KEY &&
      option.value.toLowerCase() === normalized.toLowerCase(),
  );
  return preset?.value || normalized;
};

const getOfferTypePickerLabel = (value) =>
  OFFER_TYPE_DROPDOWN_OPTIONS.find((option) => option.value === value)?.label ||
  "Select offer type";

const getOfferTypeDraftFromValue = (value) => {
  const normalized = normalizeOfferTypeSelection(value);
  const preset = OFFER_TYPE_DROPDOWN_OPTIONS.find(
    (option) =>
      option.value !== OFFER_TYPE_OTHER_KEY &&
      option.value.toLowerCase() === normalized.toLowerCase(),
  );
  if (preset?.value) {
    return { typePreset: preset.value, typeCustom: "" };
  }
  return {
    typePreset: OFFER_TYPE_OTHER_KEY,
    typeCustom: String(value || "").trim(),
  };
};

const resolveOfferTypeDraftValue = (typePreset, typeCustom) => {
  if (typePreset === OFFER_TYPE_OTHER_KEY) {
    return normalizeOfferTypeSelection(typeCustom);
  }
  return normalizeOfferTypeSelection(typePreset);
};

const OFFER_RENEW_WINDOW_MS = 5 * 24 * 60 * 60 * 1000;
const OFFER_EXPIRY_DEFAULT_TIME = "17:00";

const padDatePart = (value) => String(value).padStart(2, "0");

const buildOfferExpiryDateOptions = (daysAhead = 365) => {
  const options = [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let index = 0; index <= daysAhead; index += 1) {
    const valueDate = new Date(today);
    valueDate.setDate(today.getDate() + index);
    const dateValue = [
      valueDate.getFullYear(),
      padDatePart(valueDate.getMonth() + 1),
      padDatePart(valueDate.getDate()),
    ].join("-");
    const dateLabel = valueDate.toLocaleDateString([], {
      weekday: "short",
      month: "short",
      day: "numeric",
      year: "numeric",
    });
    const label =
      index === 0
        ? `Today (${dateLabel})`
        : index === 1
          ? `Tomorrow (${dateLabel})`
          : dateLabel;
    options.push({ value: dateValue, label });
  }
  return options;
};

const OFFER_EXPIRY_TIME_OPTIONS = Array.from({ length: 48 }, (_, index) => {
  const hours = Math.floor(index / 2);
  const minutes = index % 2 === 0 ? 0 : 30;
  const value = `${padDatePart(hours)}:${padDatePart(minutes)}`;
  const sampleDate = new Date(2020, 0, 1, hours, minutes, 0, 0);
  const label = sampleDate.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });
  return { value, label };
});

const OFFER_MONTH_OPTIONS = Array.from({ length: 12 }, (_, index) => {
  const monthIndex = index + 1;
  const sampleDate = new Date(2020, index, 1);
  return {
    value: monthIndex,
    label: sampleDate.toLocaleDateString([], { month: "long" }),
  };
});

const getDaysInMonth = (year, month) => {
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    month < 1 ||
    month > 12
  ) {
    return 31;
  }
  return new Date(year, month, 0).getDate();
};

const parseOfferExpiryIso = (dateValue, timeValue) => {
  const safeDate = String(dateValue || "").trim();
  const safeTime = String(timeValue || "").trim();
  if (!safeDate && !safeTime) return { iso: null, valid: true };
  if (!safeDate || !safeTime) return { iso: null, valid: false };
  const dateMatch = safeDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const timeMatch = safeTime.match(/^(\d{2}):(\d{2})$/);
  if (!dateMatch || !timeMatch) return { iso: null, valid: false };
  const year = Number(dateMatch[1]);
  const month = Number(dateMatch[2]);
  const day = Number(dateMatch[3]);
  const hours = Number(timeMatch[1]);
  const minutes = Number(timeMatch[2]);
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day) ||
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > 31 ||
    !Number.isInteger(hours) ||
    !Number.isInteger(minutes) ||
    hours < 0 ||
    hours > 23 ||
    minutes < 0 ||
    minutes > 59
  ) {
    return { iso: null, valid: false };
  }
  const parsed = new Date(year, month - 1, day, hours, minutes, 0, 0);
  if (Number.isNaN(parsed.getTime())) return { iso: null, valid: false };
  if (
    parsed.getFullYear() !== year ||
    parsed.getMonth() !== month - 1 ||
    parsed.getDate() !== day
  ) {
    return { iso: null, valid: false };
  }
  return { iso: parsed.toISOString(), valid: true };
};

const parseOfferStartIso = (dateValue, timeValue) => {
  const safeDate = String(dateValue || "").trim();
  const safeTime = String(timeValue || "").trim();
  if (!safeDate && !safeTime) return { iso: null, valid: true };
  if (!safeDate || !safeTime) return { iso: null, valid: false };
  const dateMatch = safeDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const timeMatch = safeTime.match(/^(\d{2}):(\d{2})$/);
  if (!dateMatch || !timeMatch) return { iso: null, valid: false };
  const year = Number(dateMatch[1]);
  const month = Number(dateMatch[2]);
  const day = Number(dateMatch[3]);
  const hours = Number(timeMatch[1]);
  const minutes = Number(timeMatch[2]);
  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day) ||
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > 31 ||
    !Number.isInteger(hours) ||
    !Number.isInteger(minutes) ||
    hours < 0 ||
    hours > 23 ||
    minutes < 0 ||
    minutes > 59
  ) {
    return { iso: null, valid: false };
  }
  const parsed = new Date(year, month - 1, day, hours, minutes, 0, 0);
  if (Number.isNaN(parsed.getTime())) return { iso: null, valid: false };
  if (
    parsed.getFullYear() !== year ||
    parsed.getMonth() !== month - 1 ||
    parsed.getDate() !== day
  ) {
    return { iso: null, valid: false };
  }
  return { iso: parsed.toISOString(), valid: true };
};

const formatOfferExpiryLabel = (value) => {
  if (!value) return "No expiration";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "No expiration";
  const dateLabel = date.toLocaleDateString([], {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
  const timeLabel = date.toLocaleTimeString([], {
    hour: "numeric",
    minute: "2-digit",
  });
  return `${dateLabel} at ${timeLabel}`;
};

const getOfferRenewWindowLabel = (expiresAt) => {
  const expiryMs = Number(expiresAt);
  if (!Number.isFinite(expiryMs)) return null;
  const remainingMs = expiryMs - Date.now();
  if (remainingMs <= 0 || remainingMs > OFFER_RENEW_WINDOW_MS) return null;
  const remainingDays = Math.ceil(remainingMs / (24 * 60 * 60 * 1000));
  if (remainingDays <= 1) return "under 1 day left";
  return `${remainingDays} days left`;
};

const getOfferExpiryDraftFromTimestamp = (value) => {
  const fallback = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  fallback.setHours(17, 0, 0, 0);
  const date =
    Number.isFinite(Number(value)) && Number(value) > Date.now()
      ? new Date(Number(value))
      : fallback;
  if (Number.isNaN(date.getTime())) {
    return {
      expiresDate: "",
      expiresTime: "",
    };
  }
  const roundedMinutes = date.getMinutes() >= 30 ? 30 : 0;
  return {
    expiresDate: [
      date.getFullYear(),
      padDatePart(date.getMonth() + 1),
      padDatePart(date.getDate()),
    ].join("-"),
    expiresTime: `${padDatePart(date.getHours())}:${padDatePart(
      roundedMinutes,
    )}`,
  };
};

const normalizeTagsInput = (value) =>
  String(value || "")
    .split(",")
    .map((tag) => tag.trim().toLowerCase())
    .filter(Boolean);

const normalizeMerchantDescriptorAliasesInput = (value) => {
  const seen = new Set();
  return String(value || "")
    .split(/[\n,;]+/)
    .map((item) => item.trim())
    .filter((item) => item.length > 0)
    .filter((item) => {
      const key = item.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, 25);
};

const formatMerchantDescriptorAliasesInput = (aliases) =>
  Array.isArray(aliases) ? aliases.filter(Boolean).join("\n") : "";

const normalizeReferralCode = (value) =>
  String(value || "")
    .trim()
    .replace(/\s+/g, "")
    .toUpperCase();

const getReferralClaimMessage = (status) => {
  const normalized = String(status || "")
    .trim()
    .toLowerCase();
  if (normalized === "pending") {
    return "Referral claimed. Your $5 will unlock after your first verified purchase.";
  }
  if (normalized === "already_pending") {
    return "Referral is already claimed and waiting for your first verified purchase.";
  }
  if (normalized === "already_rewarded") {
    return "Referral reward was already completed on this account.";
  }
  if (normalized === "already_capped") {
    return "Referral is complete. Referrer payout was capped this month.";
  }
  return "Referral status updated.";
};

const getReferralClaimStatusMeta = (status) => {
  const normalized = String(status || "")
    .trim()
    .toLowerCase();
  if (!normalized || normalized === "none") return null;
  if (normalized === "pending" || normalized === "already_pending") {
    return {
      label: "Pending verification",
      icon: "time-outline",
      tone: "pending",
    };
  }
  if (normalized === "rewarded" || normalized === "already_rewarded") {
    return {
      label: "Rewarded",
      icon: "checkmark-circle-outline",
      tone: "rewarded",
    };
  }
  if (
    normalized === "capped" ||
    normalized === "already_capped" ||
    normalized === "rewarded_referred_only_referrer_capped"
  ) {
    return {
      label: "Reward capped this month",
      icon: "shield-outline",
      tone: "capped",
    };
  }
  return {
    label: normalized.replace(/_/g, " "),
    icon: "information-circle-outline",
    tone: "neutral",
  };
};

const parseAuthCallbackParams = (url) => {
  const value = String(url || "");
  const hashIndex = value.indexOf("#");
  const queryIndex = value.indexOf("?");
  const queryPart =
    queryIndex >= 0
      ? value.slice(queryIndex + 1, hashIndex >= 0 ? hashIndex : undefined)
      : "";
  const hashPart = hashIndex >= 0 ? value.slice(hashIndex + 1) : "";
  const merged = [queryPart, hashPart].filter(Boolean).join("&");
  const params = new URLSearchParams(merged);
  return {
    code: params.get("code") || null,
    accessToken: params.get("access_token") || null,
    refreshToken: params.get("refresh_token") || null,
    flow: params.get("flow") || null,
    type: params.get("type") || null,
    tokenHash: params.get("token_hash") || null,
    ref: params.get("ref") || null,
    error:
      params.get("error_description") ||
      params.get("error") ||
      params.get("message") ||
      null,
  };
};

const NotificationToggle = ({ value, onValueChange, disabled = false }) => {
  const isOn = Boolean(value);
  return (
    <TouchableOpacity
      activeOpacity={0.85}
      disabled={disabled}
      onPress={() => onValueChange(!isOn)}
      accessibilityRole="switch"
      accessibilityState={{ checked: isOn, disabled }}
      style={styles.notificationToggleHitbox}
    >
      <View
        style={[
          styles.notificationToggleTrack,
          isOn && styles.notificationToggleTrackActive,
          disabled && styles.notificationToggleTrackDisabled,
        ]}
      >
        <View
          style={[
            styles.notificationToggleThumb,
            isOn && styles.notificationToggleThumbActive,
          ]}
        />
      </View>
    </TouchableOpacity>
  );
};
// Fast-refresh compatibility: keep `Switch` defined so stale render branches
// don't crash while the app updates to NotificationToggle.
const Switch = NotificationToggle;

const sanitizeBusinessTags = (tags) =>
  (Array.isArray(tags) ? tags : [])
    .map((tag) => String(tag || "").trim())
    .filter(Boolean)
    .filter((tag) => tag.toLowerCase() !== "local")
    .filter((tag) => !tag.startsWith("__wello_"));

const clampValue = (value, min, max) => Math.min(max, Math.max(min, value));

const decodeJwtPayloadClient = (token) => {
  if (!token) return null;
  const parts = String(token).split(".");
  if (parts.length < 2) return null;
  const base64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
  const padded = base64 + "=".repeat((4 - (base64.length % 4)) % 4);
  try {
    const bytes = toByteArray(padded);
    const json = String.fromCharCode(...bytes);
    return JSON.parse(json);
  } catch {
    return null;
  }
};

const withTimeout = (promise, ms, label) =>
  Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`${label} timeout`)), ms),
    ),
  ]);

const createIdempotencyKey = () => {
  if (globalThis?.crypto?.randomUUID) {
    return globalThis.crypto.randomUUID();
  }
  return `req_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 12)}`;
};

const formatPlaidFunctionError = (parsed, fallbackMessage) => {
  const code = String(
    parsed?.plaid_error_code || parsed?.code || "",
  ).toUpperCase();
  switch (code) {
    case "MISSING_FIELDS":
    case "INVALID_FIELD":
    case "INVALID_REQUEST":
      return PLAID_LINK_UNAVAILABLE_COPY;
    case "NO_AUTH_ACCOUNTS":
      return "No checking or savings account was shared. Link a bank and select a checking or savings account.";
    case "ITEM_LOGIN_REQUIRED":
      return "Your bank connection needs to be relinked.";
    case "INVALID_ACCESS_TOKEN":
      return "Bank connection expired. Please relink your bank.";
    case "INSUFFICIENT_CREDENTIALS":
      return "Bank permissions are incomplete. Please relink and allow required access.";
    case "INSTITUTION_NOT_RESPONDING":
      return "Your bank is temporarily unavailable. Try again shortly.";
    default:
      return (
        String(parsed?.error || parsed?.message || "").trim() ||
        String(fallbackMessage || "").trim() ||
        "Verification request failed."
      );
  }
};

const toUserFacingError = (
  message,
  fallback = "Something went wrong. Please try again.",
) => {
  const raw = String(message || "")
    .replace(/\s+/g, " ")
    .trim();
  if (!raw) return fallback;
  const lower = raw.toLowerCase();

  if (
    lower.includes("timeout") ||
    lower.includes("edge_invoke") ||
    lower.includes("stripe_invoke") ||
    lower.includes("plaid_invoke") ||
    lower.includes("r2_invoke")
  ) {
    return "The request took too long. Please try again.";
  }
  if (
    lower.includes("network request failed") ||
    lower.includes("failed to fetch") ||
    lower.includes("network error")
  ) {
    return "Network issue. Check your connection and try again.";
  }
  if (
    lower.includes("invalid jwt") ||
    lower.includes("jwt expired") ||
    lower.includes("unauthorized") ||
    lower.includes("missing authorization")
  ) {
    return "Your session expired. Please sign in again.";
  }
  if (
    lower.includes("debug") ||
    lower.includes("stack") ||
    lower.includes("trace") ||
    lower.includes("exception")
  ) {
    return fallback;
  }
  if (
    lower.includes("payload") ||
    lower.includes("request id") ||
    lower.includes("api key") ||
    lower.includes("provided was invalid") ||
    lower.includes("validation failure") ||
    lower.includes("sqlstate") ||
    lower.includes("context:") ||
    lower.includes("line ") ||
    lower.includes("supabase is not configured")
  ) {
    return fallback;
  }
  if (
    (raw.includes("{") && raw.includes("}")) ||
    (raw.includes("[") && raw.includes("]")) ||
    /\"errors?\"\s*:/i.test(raw)
  ) {
    return fallback;
  }
  if (/https?:\/\//i.test(raw) && raw.length > 80) {
    return fallback;
  }

  const sanitized = raw
    .replace(/sk_(test|live)_[A-Za-z0-9]+/g, "sk_****")
    .replace(/acct_[A-Za-z0-9]+/g, "acct_****");
  if (sanitized.length > 140) {
    return fallback;
  }
  return sanitized;
};

const safeLocalSignOut = async () => {
  try {
    await clearSupabaseSession();
  } catch (error) {
    console.warn("Failed to clear Supabase session", error?.message);
  }
  try {
    await withTimeout(
      supabase.auth.signOut({ scope: "local" }),
      8000,
      "signOut",
    );
  } catch (error) {
    console.warn("Supabase signOut failed", error?.message);
  }
};

const callStripeFunction = async (functionName, payload) => {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return { data: null, error: "Supabase is not configured.", status: null };
  }
  const refreshResult = refreshSupabaseClient();
  if (!refreshResult.ok) {
    return { data: null, error: refreshResult.error, status: null };
  }

  const tokenResult = await getAccessTokenWithFallback(6000);
  let accessToken = tokenResult.accessToken;
  if (!accessToken) {
    const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
      persist: false,
    });
    accessToken = refreshed?.accessToken || "";
  }
  if (!accessToken) {
    return { data: null, error: "Sign in again to continue.", status: null };
  }

  const tokenPayload = decodeJwtPayloadClient(accessToken);
  const issuer = tokenPayload?.iss || "";
  const expectedIssuer = SUPABASE_URL
    ? `${SUPABASE_URL.replace(/\/+$/, "")}/auth/v1`
    : "";
  const refreshForStripe = async () =>
    refreshAccessTokenWithRefreshToken(6000, { persist: false });
  if (expectedIssuer && issuer && issuer !== expectedIssuer) {
    const refreshed = await refreshForStripe();
    if (refreshed?.accessToken) {
      accessToken = refreshed.accessToken;
    } else {
      return {
        data: null,
        error: "Session belongs to a different project. Please sign in again.",
        status: null,
      };
    }
  }
  const exp = Number(tokenPayload?.exp);
  if (Number.isFinite(exp) && exp * 1000 < Date.now()) {
    const refreshed = await refreshForStripe();
    if (refreshed?.accessToken) {
      accessToken = refreshed.accessToken;
    } else {
      return {
        data: null,
        error: "Session expired. Please sign in again.",
        status: null,
      };
    }
  }

  const runRequest = async (token) => {
    const startTime = Date.now();
    const body = { ...(payload || {}) };
    const response = await withTimeout(
      supabase.functions.invoke(functionName, {
        body,
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }),
      12000,
      "stripe_invoke",
    );
    if (!response?.error) {
      let parsedData = response?.data ?? null;
      if (typeof parsedData === "string") {
        try {
          parsedData = parsedData ? JSON.parse(parsedData) : null;
        } catch {
          parsedData = response?.data ?? null;
        }
      }
      return {
        ok: true,
        status: 200,
        parsed: parsedData,
        rawText:
          typeof parsedData === "string"
            ? parsedData
            : parsedData
              ? JSON.stringify(parsedData)
              : "",
        errorMessage: null,
        durationMs: Date.now() - startTime,
      };
    }

    const err = response.error;
    const context = err?.context;
    const status = context?.status ?? null;
    let rawText = "";
    let parsed = null;
    if (context?.text) {
      try {
        rawText = await context.text();
      } catch {
        rawText = "";
      }
    }
    try {
      parsed = rawText ? JSON.parse(rawText) : null;
    } catch {
      parsed = null;
    }
    const baseErrorMessage =
      parsed?.error ||
      parsed?.message ||
      err?.message ||
      (status
        ? `Stripe request failed (${status}).`
        : "Stripe request failed.");
    const errorMessage =
      parsed?.phase && typeof parsed.phase === "string"
        ? `${baseErrorMessage} (phase: ${parsed.phase})`
        : baseErrorMessage;
    return {
      ok: false,
      status,
      parsed,
      rawText,
      errorMessage,
      durationMs: Date.now() - startTime,
    };
  };

  try {
    let attempt = await runRequest(accessToken);
    const rawTextLower = String(attempt.rawText || "").toLowerCase();
    const parsedMessage = String(
      attempt.parsed?.message || attempt.parsed?.error || "",
    ).toLowerCase();
    const isAuthFailure =
      attempt.status === 401 ||
      rawTextLower.includes("invalid jwt") ||
      rawTextLower.includes("jwt expired") ||
      rawTextLower.includes("unauthorized") ||
      rawTextLower.includes("missing authorization") ||
      parsedMessage.includes("invalid jwt") ||
      parsedMessage.includes("jwt expired") ||
      parsedMessage.includes("unauthorized") ||
      parsedMessage.includes("missing authorization");

    if (!attempt.ok && isAuthFailure) {
      try {
        const refreshResult = await refreshAccessTokenWithRefreshToken(6000, {
          persist: false,
        });
        const refreshedToken = refreshResult?.accessToken || "";
        if (refreshedToken) {
          attempt = await runRequest(refreshedToken);
        }
      } catch (_error) {}
    }

    if (!attempt.ok) {
      console.warn("Stripe function failed", {
        functionName,
        status: attempt.status,
        error: attempt.errorMessage,
        parsed: attempt.parsed,
        raw: attempt.rawText,
      });
      return {
        data: null,
        error: toUserFacingError(
          attempt.errorMessage,
          "Unable to complete this request right now.",
        ),
        status: attempt.status,
        details: attempt.parsed ?? null,
      };
    }
    return {
      data: attempt.parsed ?? null,
      error: null,
      status: attempt.status,
      details: null,
    };
  } catch (error) {
    return {
      data: null,
      error: toUserFacingError(
        error?.message || "Stripe request failed.",
        "Unable to complete this request right now.",
      ),
      status: null,
      details: null,
    };
  }
};

const callPlaidFunction = async (functionName, payload) => {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return { data: null, error: "Supabase is not configured.", status: null };
  }
  const refreshResult = refreshSupabaseClient();
  if (!refreshResult.ok) {
    return { data: null, error: refreshResult.error, status: null };
  }

  const tokenResult = await getAccessTokenWithFallback(6000);
  let accessToken = tokenResult.accessToken;
  if (!accessToken) {
    const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
      persist: false,
    });
    accessToken = refreshed?.accessToken || "";
  }
  if (!accessToken) {
    return { data: null, error: "Sign in again to continue.", status: null };
  }

  const tokenPayload = decodeJwtPayloadClient(accessToken);
  const issuer = tokenPayload?.iss || "";
  const expectedIssuer = SUPABASE_URL
    ? `${SUPABASE_URL.replace(/\/+$/, "")}/auth/v1`
    : "";
  const refreshForPlaid = async () =>
    refreshAccessTokenWithRefreshToken(6000, { persist: false });
  if (expectedIssuer && issuer && issuer !== expectedIssuer) {
    const refreshed = await refreshForPlaid();
    if (refreshed?.accessToken) {
      accessToken = refreshed.accessToken;
    } else {
      return {
        data: null,
        error: "Session belongs to a different project. Please sign in again.",
        status: null,
      };
    }
  }
  const exp = Number(tokenPayload?.exp);
  if (Number.isFinite(exp) && exp * 1000 < Date.now()) {
    const refreshed = await refreshForPlaid();
    if (refreshed?.accessToken) {
      accessToken = refreshed.accessToken;
    } else {
      return {
        data: null,
        error: "Session expired. Please sign in again.",
        status: null,
      };
    }
  }

  const runRequest = async (token) => {
    const startTime = Date.now();
    const body = { ...(payload || {}) };
    const response = await withTimeout(
      supabase.functions.invoke(functionName, {
        body,
        headers: {
          Authorization: `Bearer ${token}`,
        },
      }),
      12000,
      "plaid_invoke",
    );
    if (!response?.error) {
      let parsedData = response?.data ?? null;
      if (typeof parsedData === "string") {
        try {
          parsedData = parsedData ? JSON.parse(parsedData) : null;
        } catch {
          parsedData = response?.data ?? null;
        }
      }
      return {
        ok: true,
        status: 200,
        parsed: parsedData,
        rawText:
          typeof parsedData === "string"
            ? parsedData
            : parsedData
              ? JSON.stringify(parsedData)
              : "",
        errorMessage: null,
        durationMs: Date.now() - startTime,
      };
    }

    const err = response.error;
    const context = err?.context;
    const status = context?.status ?? null;
    let rawText = "";
    let parsed = null;
    if (context?.text) {
      try {
        rawText = await context.text();
      } catch {
        rawText = "";
      }
    }
    try {
      parsed = rawText ? JSON.parse(rawText) : null;
    } catch {
      parsed = null;
    }
    let baseErrorMessage = formatPlaidFunctionError(
      parsed,
      err?.message ||
        (status
          ? `Verification request failed (${status}).`
          : "Verification request failed."),
    );
    const numericStatus = Number(status) || 0;
    const hasParsedPayload =
      parsed && typeof parsed === "object" && Object.keys(parsed).length > 0;
    if (!hasParsedPayload && [502, 503, 504].includes(numericStatus)) {
      baseErrorMessage =
        "Bank linking is temporarily unavailable. Please try again in a moment.";
    }
    return {
      ok: false,
      status,
      parsed,
      rawText,
      errorMessage: baseErrorMessage,
      durationMs: Date.now() - startTime,
    };
  };

  try {
    let attempt = await runRequest(accessToken);
    const rawTextLower = String(attempt.rawText || "").toLowerCase();
    const parsedMessage = String(
      attempt.parsed?.message || attempt.parsed?.error || "",
    ).toLowerCase();
    const isAuthFailure =
      attempt.status === 401 ||
      rawTextLower.includes("invalid jwt") ||
      rawTextLower.includes("jwt expired") ||
      rawTextLower.includes("unauthorized") ||
      rawTextLower.includes("missing authorization") ||
      parsedMessage.includes("invalid jwt") ||
      parsedMessage.includes("jwt expired") ||
      parsedMessage.includes("unauthorized") ||
      parsedMessage.includes("missing authorization");

    if (!attempt.ok && isAuthFailure) {
      try {
        const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
          persist: false,
        });
        const refreshedToken = refreshed?.accessToken || "";
        if (refreshedToken) {
          accessToken = refreshedToken;
          attempt = await runRequest(refreshedToken);
        }
      } catch (_error) {}
    }

    const transientUpstreamError =
      !attempt.ok && [502, 503, 504].includes(Number(attempt.status) || 0);
    if (transientUpstreamError) {
      await new Promise((resolve) => setTimeout(resolve, 600));
      attempt = await runRequest(accessToken);
    }

    if (!attempt.ok) {
      return {
        data: null,
        error: toUserFacingError(
          attempt.errorMessage,
          "Unable to complete verification right now.",
        ),
        status: attempt.status,
        details: attempt.parsed ?? null,
      };
    }
    return {
      data: attempt.parsed ?? null,
      error: null,
      status: attempt.status,
      details: null,
    };
  } catch (error) {
    return {
      data: null,
      error: toUserFacingError(
        error?.message || "Verification request failed.",
        "Unable to complete verification right now.",
      ),
      status: null,
      details: null,
    };
  }
};

const callR2Presign = async (payload) => {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return { data: null, error: "Supabase is not configured.", status: null };
  }
  const refreshResult = refreshSupabaseClient();
  if (!refreshResult.ok) {
    return { data: null, error: refreshResult.error, status: null };
  }
  let accessToken = (await getAccessTokenWithFallback(6000)).accessToken;
  if (!accessToken) {
    return { data: null, error: "Sign in again to continue.", status: null };
  }
  const tokenPayload = decodeJwtPayloadClient(accessToken);
  const expectedIssuer = SUPABASE_URL
    ? `${SUPABASE_URL.replace(/\/+$/, "")}/auth/v1`
    : "";
  const exp = Number(tokenPayload?.exp);
  const isExpired = Number.isFinite(exp) && exp * 1000 < Date.now();
  const issuerMismatch =
    expectedIssuer && tokenPayload?.iss && tokenPayload.iss !== expectedIssuer;
  if (isExpired || issuerMismatch) {
    const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
      persist: false,
    });
    if (refreshed?.accessToken) {
      accessToken = refreshed.accessToken;
    }
  }
  try {
    const runInvoke = async (token) => {
      const response = await withTimeout(
        supabase.functions.invoke("r2-presign", {
          body: { ...(payload || {}) },
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }),
        12000,
        "r2_invoke",
      );
      if (!response?.error) {
        let parsedData = response?.data ?? null;
        if (typeof parsedData === "string") {
          try {
            parsedData = parsedData ? JSON.parse(parsedData) : null;
          } catch {
            parsedData = response?.data ?? null;
          }
        }
        return {
          ok: true,
          status: 200,
          parsed: parsedData,
          rawText:
            typeof parsedData === "string"
              ? parsedData
              : parsedData
                ? JSON.stringify(parsedData)
                : "",
        };
      }
      const err = response.error;
      const context = err?.context;
      const status = context?.status ?? null;
      let rawText = "";
      let parsed = null;
      if (context?.text) {
        try {
          rawText = await context.text();
        } catch {
          rawText = "";
        }
      }
      try {
        parsed = rawText ? JSON.parse(rawText) : null;
      } catch {
        parsed = null;
      }
      return { ok: false, status, parsed, rawText };
    };

    let attempt = await runInvoke(accessToken);
    const rawLower = String(attempt.rawText || "").toLowerCase();
    const isAuthError =
      attempt.status === 401 ||
      rawLower.includes("invalid jwt") ||
      rawLower.includes("jwt expired") ||
      rawLower.includes("unauthorized");
    if (!attempt.ok && isAuthError) {
      const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
        persist: false,
      });
      if (refreshed?.accessToken) {
        accessToken = refreshed.accessToken;
        attempt = await runInvoke(refreshed.accessToken);
      }
    }
    if (!attempt.ok) {
      console.warn("R2 presign failed", {
        status: attempt.status,
        message: attempt.parsed?.error || attempt.parsed?.message || null,
      });
      return {
        data: null,
        error: toUserFacingError(
          attempt.parsed?.error ||
            attempt.parsed?.message ||
            "Unable to sign receipt URL.",
          "Unable to prepare receipt upload right now.",
        ),
        status: attempt.status || null,
      };
    }
    return { data: attempt.parsed, error: null, status: attempt.status };
  } catch (error) {
    console.warn("R2 presign exception");
    return {
      data: null,
      error: toUserFacingError(
        error?.message || "Unable to sign receipt URL.",
        "Unable to prepare receipt upload right now.",
      ),
      status: null,
    };
  }
};

const formatStripeError = (error) => {
  if (!error) return "";
  const message = String(error);
  if (message.includes("does not have access to account")) {
    return "Stripe account mismatch. Please reconnect your Stripe account.";
  }
  return message
    .replace(/sk_(test|live)_[A-Za-z0-9]+/g, "sk_****")
    .replace(/acct_[A-Za-z0-9]+/g, "acct_****");
};

// Note: avoid dynamic `import()` here. Metro can intermittently fail to include
// dynamically imported modules in dev, causing "Requiring unknown module" at runtime.
const loadImageManipulator = async () => ImageManipulator;

const formatMetricValue = (value) => {
  if (value === null || value === undefined) return "--";
  if (typeof value === "number") return value.toLocaleString();
  const text = String(value).trim();
  return text.length ? text : "--";
};

const formatCurrencyFromCents = (cents) => {
  const amount = Number.isFinite(Number(cents)) ? Number(cents) : 0;
  return `$${(amount / 100).toFixed(2)}`;
};

const sanitizeCashoutDigits = (value) =>
  String(value ?? "")
    .replace(/\D/g, "")
    .slice(0, 9);

const formatCashoutAmountInput = (value) => {
  const digits = sanitizeCashoutDigits(value);
  if (!digits) return "0.00";
  const padded = digits.padStart(3, "0");
  const dollars = padded.slice(0, -2).replace(/^0+(?=\d)/, "") || "0";
  const cents = padded.slice(-2);
  return `${dollars}.${cents}`;
};

const parseCashoutAmountToCents = (value) => {
  const digits = sanitizeCashoutDigits(value);
  if (!digits) return null;
  const cents = Number(digits);
  return Number.isFinite(cents) ? cents : null;
};

const BankTransferAmountInput = React.memo(function BankTransferAmountInput({
  style,
  resetKey,
  onAmountChange,
}) {
  const [value, setValue] = useState("0.00");
  const updateTimerRef = useRef(null);
  useEffect(() => {
    setValue("0.00");
    onAmountChange("0.00");
  }, [resetKey, onAmountChange]);
  useEffect(
    () => () => {
      if (updateTimerRef.current) clearTimeout(updateTimerRef.current);
    },
    [],
  );
  return (
    <TextInput
      style={style}
      value={value}
      onChangeText={(nextValue) => {
        const formatted = formatCashoutAmountInput(nextValue);
        setValue(formatted);
        if (updateTimerRef.current) clearTimeout(updateTimerRef.current);
        updateTimerRef.current = setTimeout(() => onAmountChange(formatted), 100);
      }}
      onBlur={() => onAmountChange(value)}
      placeholder="0.00"
      placeholderTextColor={COLORS.muted}
      keyboardType="decimal-pad"
      returnKeyType="done"
      selectTextOnFocus
    />
  );
});

const computeContainedSize = (
  viewportWidth,
  viewportHeight,
  imageWidth,
  imageHeight,
) => {
  const vw = Number(viewportWidth) || 0;
  const vh = Number(viewportHeight) || 0;
  const iw = Number(imageWidth) || 0;
  const ih = Number(imageHeight) || 0;
  if (!vw || !vh) return { width: 0, height: 0 };
  if (!iw || !ih) return { width: vw, height: vh };
  const scale = Math.min(vw / iw, vh / ih);
  return { width: iw * scale, height: ih * scale };
};

const computeCoverSize = (
  viewportWidth,
  viewportHeight,
  imageWidth,
  imageHeight,
) => {
  const vw = Number(viewportWidth) || 0;
  const vh = Number(viewportHeight) || 0;
  const iw = Number(imageWidth) || 0;
  const ih = Number(imageHeight) || 0;
  if (!vw || !vh) return { width: 0, height: 0 };
  if (!iw || !ih) return { width: vw, height: vh };
  const scale = Math.max(vw / iw, vh / ih);
  return { width: iw * scale, height: ih * scale };
};

const openMapsForBusiness = async (business) => {
  if (!business) return;
  const latitude =
    business.coordinate?.latitude ?? business.latitude ?? business.lat ?? null;
  const longitude =
    business.coordinate?.longitude ??
    business.longitude ??
    business.lng ??
    null;
  const addressParts = [
    business.address,
    business.city,
    business.state,
    business.postalCode,
  ]
    .map((part) => String(part || "").trim())
    .filter(Boolean);
  const address = addressParts.join(", ");
  const destination =
    latitude && longitude
      ? `${latitude},${longitude}`
      : address
        ? encodeURIComponent(address)
        : null;
  if (!destination) return;

  // Prefer native maps apps over web on iOS to avoid App Store prompts.
  const destinationParam = encodeURIComponent(
    latitude && longitude ? `${latitude},${longitude}` : address,
  );
  const googleWebUrl = `https://www.google.com/maps/dir/?api=1&destination=${destinationParam}`;

  if (Platform.OS === "ios") {
    const appleMapsUrl =
      latitude && longitude
        ? `maps://?daddr=${latitude},${longitude}`
        : `maps://?daddr=${destinationParam}`;
    try {
      await Linking.openURL(appleMapsUrl);
      return;
    } catch (error) {
      // Fall back to the web if the scheme is blocked (rare).
      await Linking.openURL(googleWebUrl).catch(() => null);
      return;
    }
  }

  if (Platform.OS === "android") {
    const navigationUrl =
      latitude && longitude
        ? `google.navigation:q=${encodeURIComponent(`${latitude},${longitude}`)}`
        : `google.navigation:q=${destinationParam}`;
    try {
      await Linking.openURL(navigationUrl);
      return;
    } catch (error) {
      const geoUrl =
        latitude && longitude
          ? `geo:${latitude},${longitude}?q=${encodeURIComponent(
              `${latitude},${longitude}`,
            )}`
          : `geo:0,0?q=${destinationParam}`;
      await Linking.openURL(geoUrl).catch(() =>
        Linking.openURL(googleWebUrl).catch(() => null),
      );
      return;
    }
  }

  Linking.openURL(googleWebUrl).catch(() => null);
};

const openPhoneForBusiness = async (business) => {
  if (!business) return;
  const rawPhone = String(
    business?.phone ||
      business?.phoneNumber ||
      business?.contactPhone ||
      business?.business?.phone ||
      "",
  ).trim();
  const digits = rawPhone.replace(/[^\d+]/g, "");
  if (!digits) return;
  const telUrl = `tel:${digits}`;
  Linking.openURL(telUrl).catch(() => null);
};

const parseClockMinutes = (time, meridiem) => {
  if (!time) return null;
  const [hoursRaw, minutesRaw = "0"] = String(time).split(":");
  const hours = Number(hoursRaw);
  const minutes = Number(minutesRaw);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  const normalizedHours = ((hours % 12) + 12) % 12;
  const isPm = String(meridiem).toUpperCase() === "PM";
  return (normalizedHours + (isPm ? 12 : 0)) * 60 + minutes;
};

const createPlacesSessionToken = () => {
  if (typeof globalThis?.crypto?.randomUUID === "function") {
    return globalThis.crypto.randomUUID();
  }
  return `wello-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
};

const normalizePlaceId = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (raw.startsWith("places/")) return raw.slice("places/".length).trim();
  return raw;
};

const normalizeAutocompletePrediction = (prediction = {}) => {
  const placeId = normalizePlaceId(prediction.placeId || prediction.place);
  if (!placeId) return null;
  const mainText =
    prediction?.structuredFormat?.mainText?.text ||
    prediction?.text?.text ||
    "";
  const secondaryText = prediction?.structuredFormat?.secondaryText?.text || "";
  const description = [mainText, secondaryText].filter(Boolean).join(", ");
  return {
    place_id: placeId,
    description: description || mainText || secondaryText || "",
    structured_formatting: {
      main_text: mainText || description || "",
      secondary_text: secondaryText || "",
    },
  };
};

const normalizePlacesAutocompletePayload = (payload) => {
  if (Array.isArray(payload?.predictions)) {
    return payload.predictions;
  }
  if (!Array.isArray(payload?.suggestions)) return [];
  return payload.suggestions
    .map((entry) => normalizeAutocompletePrediction(entry?.placePrediction))
    .filter(Boolean);
};

const normalizePlaceDetailsPayload = (payload) => {
  const place = payload?.result || payload;
  if (!place || typeof place !== "object") return null;
  const formattedAddress = String(
    place.formatted_address || place.formattedAddress || "",
  ).trim();
  const addressComponents = Array.isArray(place.address_components)
    ? place.address_components
    : Array.isArray(place.addressComponents)
      ? place.addressComponents
      : [];
  const rawLocation = place?.geometry?.location || place?.location || null;
  const latitude = Number(rawLocation?.lat ?? rawLocation?.latitude);
  const longitude = Number(rawLocation?.lng ?? rawLocation?.longitude);
  const hasCoords = Number.isFinite(latitude) && Number.isFinite(longitude);
  return {
    formatted_address: formattedAddress,
    address_components: addressComponents,
    geometry: {
      location: hasCoords ? { lat: latitude, lng: longitude } : null,
    },
  };
};

const callPlacesProxy = async (payload) => {
  if (!PLACES_PROXY_ENABLED || !PLACES_PROXY_URL) return null;
  const response = await withTimeout(
    fetch(PLACES_PROXY_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: SUPABASE_ANON_KEY,
      },
      body: JSON.stringify(payload || {}),
    }),
    9000,
    "places_proxy",
  );
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(
      data?.error || data?.message || "Address lookup is unavailable right now.",
    );
  }
  return data;
};

const fetchPlacesAutocompleteSuggestions = async (query, sessionToken) => {
  const input = String(query || "").trim();
  if (!input) return [];
  if (!PLACES_PROXY_ENABLED || !PLACES_PROXY_URL) return [];

  const payload = await callPlacesProxy({
    action: "autocomplete",
    input,
    sessionToken: sessionToken || undefined,
  });
  return normalizePlacesAutocompletePayload(payload || {});
};

const fetchPlaceDetailsResult = async (placeId, sessionToken) => {
  const normalizedPlaceId = normalizePlaceId(placeId);
  if (!normalizedPlaceId) return null;
  if (!PLACES_PROXY_ENABLED || !PLACES_PROXY_URL) return null;
  const payload = await callPlacesProxy({
    action: "details",
    placeId: normalizedPlaceId,
    sessionToken: sessionToken || undefined,
  });
  const normalized = normalizePlaceDetailsPayload(payload || {});
  if (!normalized) {
    throw new Error("Unable to load place details.");
  }
  return normalized;
};

const fetchGeocodeResult = async (address) => {
  const normalizedAddress = String(address || "").trim();
  if (!normalizedAddress) return null;
  if (!PLACES_PROXY_ENABLED || !PLACES_PROXY_URL) return null;
  const payload = await callPlacesProxy({
    action: "geocode",
    address: normalizedAddress,
  });
  const location = payload?.results?.[0]?.geometry?.location;
  if (!location) return null;
  const latitude = Number(location?.lat);
  const longitude = Number(location?.lng);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;
  return { latitude, longitude };
};

const fetchNearestRoadCoordinate = async (coordinate) => {
  const latitude = Number(coordinate?.latitude);
  const longitude = Number(coordinate?.longitude);
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;
  if (!PLACES_PROXY_ENABLED || !PLACES_PROXY_URL) return null;
  const payload = await callPlacesProxy({
    action: "nearestRoad",
    latitude,
    longitude,
  });
  const snappedLocation = payload?.snappedPoints?.[0]?.location;
  const snappedLatitude = Number(snappedLocation?.latitude);
  const snappedLongitude = Number(snappedLocation?.longitude);
  if (!Number.isFinite(snappedLatitude) || !Number.isFinite(snappedLongitude)) {
    return null;
  }
  return {
    latitude: snappedLatitude,
    longitude: snappedLongitude,
  };
};

const isBusinessOpenNow = (value) => {
  const status = getBusinessHoursStatus(value, null);
  if (!status.sourceKnown) return null;
  return status.isOpen;
};

const DAY_KEY_BY_WEEKDAY = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const CLOSING_SOON_THRESHOLD_MINUTES = 120;

const formatClockLabelFromMinutes = (minutes, lowercaseMeridiem = true) => {
  if (!Number.isFinite(minutes)) return "";
  const normalized = ((Math.round(minutes) % (24 * 60)) + 24 * 60) % (24 * 60);
  const hours24 = Math.floor(normalized / 60);
  const mins = normalized % 60;
  const meridiem = hours24 >= 12 ? "PM" : "AM";
  const hours12 = ((hours24 + 11) % 12) + 1;
  const suffix = lowercaseMeridiem ? meridiem.toLowerCase() : meridiem;
  return `${hours12}:${String(mins).padStart(2, "0")} ${suffix}`;
};

const withTimeOnDate = (baseDate, minutesFromMidnight, dayOffset = 0) => {
  const date = new Date(baseDate.getTime());
  date.setDate(date.getDate() + dayOffset);
  date.setHours(0, 0, 0, 0);
  date.setMinutes(Math.max(0, Math.floor(Number(minutesFromMidnight) || 0)));
  return date;
};

const getBusinessHoursStatus = (value, fallbackOpen = null, nowDate = new Date()) => {
  const fallbackIsOpen =
    typeof fallbackOpen === "boolean" ? fallbackOpen : null;
  const parsedSchedule = parseBusinessHoursSchedule(value);
  const buildFallback = () => {
    if (fallbackIsOpen === null) {
      return {
        sourceKnown: false,
        isOpen: false,
        minutesUntilClose: null,
        opensAtLabel: "",
        nextOpenDayLabel: "",
        closesAtLabel: "",
        statusText: "Closed",
        statusVariant: "closed",
        closedOverlayText: "Closed",
      };
    }
    return {
      sourceKnown: false,
      isOpen: fallbackIsOpen,
      minutesUntilClose: null,
      opensAtLabel: "",
      nextOpenDayLabel: "",
      closesAtLabel: "",
      statusText: fallbackIsOpen ? "Open now" : "Closed",
      statusVariant: fallbackIsOpen ? "open" : "closed",
      closedOverlayText: "Closed",
    };
  };
  if (!parsedSchedule) return buildFallback();

  const now = new Date(nowDate.getTime());
  const currentMinutes = now.getHours() * 60 + now.getMinutes();
  const todayKey = DAY_KEY_BY_WEEKDAY[now.getDay()] || "Mon";
  const prevDate = new Date(now.getTime());
  prevDate.setDate(prevDate.getDate() - 1);
  const previousDayKey = DAY_KEY_BY_WEEKDAY[prevDate.getDay()] || "Sun";
  const todayEntry = getBusinessHoursScheduleEntry(parsedSchedule, todayKey);
  const previousDayEntry = getBusinessHoursScheduleEntry(
    parsedSchedule,
    previousDayKey,
  );
  const todayStart = parseTimeValueToMinutes(todayEntry.start);
  const todayEnd = parseTimeValueToMinutes(todayEntry.end);
  const previousStart = parseTimeValueToMinutes(previousDayEntry.start);
  const previousEnd = parseTimeValueToMinutes(previousDayEntry.end);

  let isOpen = false;
  let closeAtDate = null;
  let activeEndMinutes = null;
  if (
    todayEntry.open &&
    Number.isFinite(todayStart) &&
    Number.isFinite(todayEnd)
  ) {
    if (todayStart === todayEnd) {
      isOpen = true;
      activeEndMinutes = todayEnd;
      closeAtDate = null;
    } else if (todayEnd > todayStart) {
      if (currentMinutes >= todayStart && currentMinutes <= todayEnd) {
        isOpen = true;
        activeEndMinutes = todayEnd;
        closeAtDate = withTimeOnDate(now, todayEnd, 0);
      }
    } else if (currentMinutes >= todayStart) {
      isOpen = true;
      activeEndMinutes = todayEnd;
      closeAtDate = withTimeOnDate(now, todayEnd, 1);
    }
  }
  if (
    !isOpen &&
    previousDayEntry.open &&
    Number.isFinite(previousStart) &&
    Number.isFinite(previousEnd) &&
    previousEnd < previousStart &&
    currentMinutes <= previousEnd
  ) {
    isOpen = true;
    activeEndMinutes = previousEnd;
    closeAtDate = withTimeOnDate(now, previousEnd, 0);
  }

  if (isOpen) {
    const minutesUntilClose = closeAtDate
      ? Math.max(0, Math.round((closeAtDate.getTime() - now.getTime()) / 60000))
      : null;
    const closesAtLabel = Number.isFinite(activeEndMinutes)
      ? formatClockLabelFromMinutes(activeEndMinutes, true)
      : "";
    const shouldShowClosingTime =
      Number.isFinite(minutesUntilClose) &&
      minutesUntilClose < CLOSING_SOON_THRESHOLD_MINUTES;
    return {
      sourceKnown: true,
      isOpen: true,
      minutesUntilClose,
      opensAtLabel: "",
      nextOpenDayLabel: "",
      closesAtLabel,
      statusText: shouldShowClosingTime
        ? `Closes ${closesAtLabel}`
        : "Open now",
      statusVariant: shouldShowClosingTime ? "closing" : "open",
      closedOverlayText: "",
    };
  }

  let nextOpenDate = null;
  let nextOpenMinutes = null;
  if (
    todayEntry.open &&
    Number.isFinite(todayStart) &&
    currentMinutes < todayStart
  ) {
    nextOpenDate = withTimeOnDate(now, todayStart, 0);
    nextOpenMinutes = todayStart;
  } else {
    for (let offset = 1; offset <= 7; offset += 1) {
      const candidate = new Date(now.getTime());
      candidate.setDate(candidate.getDate() + offset);
      const dayKey = DAY_KEY_BY_WEEKDAY[candidate.getDay()] || "";
      const entry = getBusinessHoursScheduleEntry(parsedSchedule, dayKey);
      const entryStart = parseTimeValueToMinutes(entry.start);
      if (!entry.open || !Number.isFinite(entryStart)) continue;
      nextOpenDate = withTimeOnDate(now, entryStart, offset);
      nextOpenMinutes = entryStart;
      break;
    }
  }
  const opensAtLabel = nextOpenDate && Number.isFinite(nextOpenMinutes)
    ? formatClockLabelFromMinutes(nextOpenMinutes, true)
    : "";
  const nextOpenDayLabel = nextOpenDate
    ? nextOpenDate.toLocaleDateString(undefined, { weekday: "short" })
    : "";
  return {
    sourceKnown: true,
    isOpen: false,
    minutesUntilClose: null,
    opensAtLabel,
    nextOpenDayLabel,
    closesAtLabel: "",
    statusText: opensAtLabel ? `Opens ${opensAtLabel}` : "Closed",
    statusVariant: "closed",
    closedOverlayText: "Closed",
  };
};

const parseAddressComponents = (components = []) => {
  const readComponentText = (component) =>
    String(
      component?.long_name ||
        component?.longText ||
        component?.short_name ||
        component?.shortText ||
        "",
    ).trim();
  const get = (type) =>
    readComponentText(
      components.find(
        (component) =>
          Array.isArray(component?.types) && component.types.includes(type),
      ),
    );
  const streetNumber = get("street_number");
  const route = get("route");
  const street = [streetNumber, route].filter(Boolean).join(" ").trim();
  return {
    street,
    city: get("locality"),
    state: get("administrative_area_level_1"),
    postalCode: get("postal_code"),
  };
};

