function normalizeBusinessCategoryKey(categoryKey) {
  const normalized = String(categoryKey || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");
  if (!normalized) return DEFAULT_BUSINESS_CATEGORY_KEY;
  return (
    LEGACY_TO_DISCOVER_CATEGORY_KEY_MAP[normalized] ||
    (KNOWN_CATEGORY_KEY_SET.has(normalized)
      ? normalized
      : DEFAULT_BUSINESS_CATEGORY_KEY)
  );
}

function getCategoryConfig(categoryKey) {
  return CATEGORY_CONFIG[normalizeBusinessCategoryKey(categoryKey)] || CATEGORY_CONFIG.default;
}

function getDiscoverHomeCategoryLabel(categoryKey) {
  return getCategoryConfig(categoryKey).display;
}

function isTradeCategoryValue(value) {
  const normalized = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (!normalized) return false;
  if (NON_TRADE_CATEGORY_KEYS.has(normalized)) return false;
  if (NON_TRADE_CATEGORY_TERMS.has(normalized)) return false;
  return true;
}

function isTradeBusinessLike(subject) {
  if (!subject || typeof subject !== "object") return false;
  const categoryCandidates = [
    subject.categoryKey,
    subject.category_key,
    subject.categoryLabel,
    subject.category_label,
  ]
    .map((value) => String(value || "").trim())
    .filter(Boolean);
  if (categoryCandidates.length) {
    return categoryCandidates.some((value) => isTradeCategoryValue(value));
  }
  const rawTags = Array.isArray(subject.tags)
    ? subject.tags
    : String(subject.tags || "")
        .split(",")
        .map((item) => item.trim())
        .filter(Boolean);
  return rawTags.some((value) => isTradeCategoryValue(value));
}

const resolveBusinessEffectiveReceiptChargeRateBps = (value) =>
  resolveBusinessReceiptChargeRateCents(value) * 10;

const resolveBusinessEffectiveDefaultCashbackRateBps = (
  commissionRateCents,
  subject,
) =>
  resolveBusinessDefaultCashbackRateBps(
    commissionRateCents ??
      subject?.commissionRateCents ??
      subject?.commission_rate_cents,
    subject?.defaultCashbackRateBps ?? subject?.default_cashback_rate_bps,
  );

const resolveDisplayedBusinessDefaultCashbackRateBps = (subject) => {
  const explicitCashbackRateBps = Number(
    subject?.defaultCashbackRateBps ?? subject?.default_cashback_rate_bps,
  );
  if (Number.isFinite(explicitCashbackRateBps)) {
    return Math.max(0, Math.round(explicitCashbackRateBps));
  }
  return resolveBusinessDefaultCashbackRateBps(
    subject?.commissionRateCents ?? subject?.commission_rate_cents,
  );
};

function isKnownCategoryKey(categoryKey) {
  return KNOWN_CATEGORY_KEY_SET.has(normalizeBusinessCategoryKey(categoryKey));
}

function getCategoryPickerLabel(categoryKey, customLabel = "") {
  const key = String(categoryKey || "").trim();
  if (key === CATEGORY_OTHER_KEY) {
    const custom = String(customLabel || "").trim();
    return custom || "Other";
  }
  const option = CATEGORY_OPTIONS.find((item) => item.key === key);
  if (option?.label) return option.label;
  if (key) return getCategoryConfig(key).display;
  return "Select category";
}

function resolveSelectedCategory(categoryKey, customLabel = "") {
  const key = String(categoryKey || "").trim();
  if (key === CATEGORY_OTHER_KEY) {
    const label = String(customLabel || "").trim();
    if (!label) {
      return {
        ok: false,
        error: "Type a category when selecting Other.",
      };
    }
    const slug = label
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 40);
    return {
      ok: true,
      categoryKey: slug ? `other-${slug}` : "other",
      categoryLabel: label,
    };
  }

  const resolvedKey = normalizeBusinessCategoryKey(key);
  return {
    ok: true,
    categoryKey: resolvedKey,
    categoryLabel: getCategoryConfig(resolvedKey).display,
  };
}

const OFFER_IMAGE_BUCKET = "offer-images";
const LEGACY_RECEIPT_BUCKET = "receipt-images";
const RECEIPT_UPLOAD_WINDOW_MS = 1000 * 60 * 60 * 24;
const RECEIPT_URL_TTL_SECONDS = 60 * 60;

