const createReceiptSignedUrl = async (path) => {
  const normalizedPath = String(path || "").trim();
  if (!normalizedPath) return null;
  if (normalizedPath.startsWith("receipts/")) {
    const { data, error } = await callR2Presign({
      action: "download",
      key: normalizedPath,
    });
    if (!error && data?.signedUrl) {
      return data.signedUrl;
    }
  }
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return null;
  try {
    const { data: legacyData } = await supabase.storage
      .from(LEGACY_RECEIPT_BUCKET)
      .createSignedUrl(normalizedPath, RECEIPT_URL_TTL_SECONDS);
    return legacyData?.signedUrl || null;
  } catch {
    return null;
  }
};

const insertReceiptUploadRecord = async ({
  redemptionId,
  businessId,
  userId,
  storagePath,
  imageHash = null,
  allowRetryResubmit = false,
}) => {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return { data: null, error: "Supabase is not configured." };
  }
  try {
    let tokenResult = await getAccessTokenWithFallback(6000);
    let accessToken = tokenResult.accessToken;
    if (!accessToken) {
      const refreshed = await refreshAccessTokenWithRefreshToken(6000, {
        persist: false,
      });
      accessToken = refreshed?.accessToken || "";
    }
    if (!accessToken) {
      return { data: null, error: "Sign in again to continue." };
    }

    const restClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      auth: {
        persistSession: false,
        autoRefreshToken: false,
        detectSessionInUrl: false,
      },
      global: {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      },
    });

    const payload = {
      redemption_id: redemptionId,
      business_id: businessId,
      user_id: userId,
      storage_path: storagePath,
      image_hash: imageHash || null,
    };
    const insertResponse = await withTimeout(
      restClient
        .from("receipt_uploads")
        .insert(payload)
        .select("id, uploaded_at, storage_path")
        .maybeSingle(),
      12000,
      "receipt_insert",
    );
    if (!insertResponse.error) {
      return {
        data: insertResponse.data,
        error: null,
        status: insertResponse.status,
      };
    }

    const message =
      insertResponse.error?.message ||
      `Unable to save receipt (${insertResponse.status || "no-status"}).`;
    const lowered = String(message).toLowerCase();
    const errorCode = String(insertResponse.error?.code || "").trim().toUpperCase();
    const duplicateReceiptRaised =
      lowered === "duplicate_receipt" ||
      (errorCode === "P0001" && lowered.includes("duplicate_receipt"));
    if (duplicateReceiptRaised) {
      return {
        data: null,
        error: "This receipt has already been submitted.",
        reason: "DUPLICATE_RECEIPT",
        status: 400,
      };
    }
    const errorDetails = String(insertResponse.error?.details || "").toLowerCase();
    const imageHashDuplicate =
      lowered.includes("image_hash") ||
      lowered.includes("idx_unique_receipt_image_hash") ||
      errorDetails.includes("image_hash") ||
      errorDetails.includes("idx_unique_receipt_image_hash");
    if (imageHashDuplicate) {
      return {
        data: null,
        error: "This receipt has already been submitted.",
        reason: "DUPLICATE_RECEIPT",
        status: 400,
      };
    }
    if (
      insertResponse.status === 409 ||
      insertResponse.error?.code === "23505" ||
      lowered.includes("duplicate") ||
      lowered.includes("unique")
    ) {
      if (allowRetryResubmit) {
        const retryRpc = await withTimeout(
          restClient.rpc("user_resubmit_rejected_receipt", {
            p_redemption_id: redemptionId,
            p_storage_path: storagePath,
          }),
          12000,
          "receipt_retry_resubmit",
        );
        if (!retryRpc.error && retryRpc.data) {
          const row = Array.isArray(retryRpc.data)
            ? retryRpc.data[0] || null
            : retryRpc.data;
          if (row?.id) {
            return {
              data: row,
              error: null,
              status: retryRpc.status ?? insertResponse.status,
              resubmitted: true,
            };
          }
        }
        if (retryRpc.error) {
          const retryMessage = String(retryRpc.error.message || "").toLowerCase();
          if (retryMessage.includes("retry_not_allowed")) {
            return {
              data: null,
              error: "Retry upload is disabled for this rejected receipt.",
              reason: "RETRY_NOT_ALLOWED",
              status: retryRpc.status ?? 403,
            };
          }
          if (retryMessage.includes("receipt_not_rejected")) {
            return {
              data: null,
              error: "Only rejected receipts can be retried.",
              reason: "RECEIPT_NOT_REJECTED",
              status: retryRpc.status ?? 409,
            };
          }
          return {
            data: null,
            error: retryRpc.error.message || "Unable to retry receipt upload.",
            reason: null,
            status: retryRpc.status ?? insertResponse.status,
          };
        }
      }
      const lookupResponse = await withTimeout(
        restClient
          .from("receipt_uploads")
          .select("id, uploaded_at, storage_path, review_status, retry_allowed")
          .eq("redemption_id", redemptionId)
          .order("uploaded_at", { ascending: false })
          .limit(1)
          .maybeSingle(),
        12000,
        "receipt_lookup",
      );
      if (!lookupResponse.error && lookupResponse.data) {
        return {
          data: lookupResponse.data,
          error: null,
          status: lookupResponse.status ?? insertResponse.status,
          duplicate: true,
        };
      }
    }

    return { data: null, error: message, status: insertResponse.status };
  } catch (error) {
    return {
      data: null,
      error: error?.message || "Unable to save receipt.",
      reason: null,
      status: null,
    };
  }
};

const getStoragePublicPath = (url, bucket) => {
  if (!url) return null;
  const token = `/storage/v1/object/public/${bucket}/`;
  const index = url.indexOf(token);
  if (index === -1) return null;
  return url.slice(index + token.length).split("?")[0];
};

const getOfferImagePath = (url) => getStoragePublicPath(url, OFFER_IMAGE_BUCKET);

const removeOfferImageByUrl = async (url) => {
  if (!url || !SUPABASE_URL || !SUPABASE_ANON_KEY) return null;
  const path = getOfferImagePath(url);
  if (!path) return null;
  const { error } = await supabase.storage
    .from(OFFER_IMAGE_BUCKET)
    .remove([path]);
  return error?.message || null;
};

const getBusinessImagePath = (url) =>
  getStoragePublicPath(url, OFFER_IMAGE_BUCKET);

const removeBusinessImageByUrl = async (url) => {
  if (!url || !SUPABASE_URL || !SUPABASE_ANON_KEY) return null;
  const path = getBusinessImagePath(url);
  if (!path) return null;
  const { error } = await supabase.storage
    .from(OFFER_IMAGE_BUCKET)
    .remove([path]);
  return error?.message || null;
};

function getPendingEditLabel(field) {
  switch (field) {
    case "name":
      return "Business name";
    case "address":
      return "Address";
    case "categoryKey":
      return "Category";
    case "offer":
      return "Offer";
    case "city":
      return "City";
    case "state":
      return "State";
    case "postalCode":
      return "Zip code";
    default:
      return "Detail";
  }
}

function formatCashbackRateLabel(percentValue) {
  const value = Number(percentValue);
  if (!Number.isFinite(value) || value <= 0) return null;
  const rounded = Math.round(value * 10) / 10;
  const label = Number.isInteger(rounded)
    ? String(rounded)
    : rounded.toFixed(1);
  return `${label}% Cashback`;
}

function formatPercentOnlyLabel(percentValue) {
  const value = Number(percentValue);
  if (!Number.isFinite(value) || value <= 0) return null;
  const rounded = Math.round(value * 10) / 10;
  const label = Number.isInteger(rounded)
    ? String(rounded)
    : rounded.toFixed(1);
  return `${label}%`;
}

function getDiscoverTouchDebugPayload(event) {
  const native = event?.nativeEvent || {};
  const touches = Array.isArray(native.touches) ? native.touches : [];
  const changedTouches = Array.isArray(native.changedTouches)
    ? native.changedTouches
    : [];
  const primaryTouch = changedTouches[0] || touches[0] || null;
  const xValue = Number(
    primaryTouch?.pageX ?? primaryTouch?.locationX ?? Number.NaN,
  );
  const yValue = Number(
    primaryTouch?.pageY ?? primaryTouch?.locationY ?? Number.NaN,
  );
  return {
    touches: touches.length,
    changedTouches: changedTouches.length,
    x: Number.isFinite(xValue) ? Math.round(xValue) : null,
    y: Number.isFinite(yValue) ? Math.round(yValue) : null,
    target: native.target ?? null,
  };
}

function getDiscoverScrollDebugPayload(event) {
  const native = event?.nativeEvent || {};
  const yValue = Number(native?.contentOffset?.y ?? Number.NaN);
  const velocityYValue = Number(native?.velocity?.y ?? Number.NaN);
  const layoutHeightValue = Number(
    native?.layoutMeasurement?.height ?? Number.NaN,
  );
  const contentHeightValue = Number(native?.contentSize?.height ?? Number.NaN);
  const layoutWidthValue = Number(
    native?.layoutMeasurement?.width ?? Number.NaN,
  );
  const contentWidthValue = Number(native?.contentSize?.width ?? Number.NaN);
  const layoutHeight = Number.isFinite(layoutHeightValue)
    ? Math.round(layoutHeightValue)
    : null;
  const contentHeight = Number.isFinite(contentHeightValue)
    ? Math.round(contentHeightValue)
    : null;
  return {
    y: Number.isFinite(yValue) ? Math.round(yValue) : 0,
    velocityY: Number.isFinite(velocityYValue)
      ? Math.round(velocityYValue * 100) / 100
      : null,
    layoutHeight,
    contentHeight,
    layoutWidth: Number.isFinite(layoutWidthValue)
      ? Math.round(layoutWidthValue)
      : null,
    contentWidth: Number.isFinite(contentWidthValue)
      ? Math.round(contentWidthValue)
      : null,
    scrollRange:
      layoutHeight !== null && contentHeight !== null
        ? Math.max(0, contentHeight - layoutHeight)
        : null,
  };
}

function getOfferCardSelectionKey(card) {
  if (!card) return null;
  const offerId = String(card.offerId || card.id || "").trim();
  if (offerId) return offerId;
  const businessId = String(card.businessId || card.business?.id || "").trim();
  const title = String(card.offerTitle || card.offer || "").trim();
  if (businessId || title) return `${businessId}:${title}`;
  return null;
}

function parseDistanceLabelMiles(value) {
  const raw = String(value || "")
    .trim()
    .toLowerCase();
  if (!raw || raw === "--") return null;
  const numeric = Number.parseFloat(raw.replace(/[^0-9.]/g, ""));
  if (!Number.isFinite(numeric)) return null;
  if (raw.includes("mi")) return numeric;
  if (raw.includes("km")) return numeric * 0.621371;
  if (raw.endsWith("m") || raw.includes(" m")) return numeric / 1609.34;
  return null;
}

function formatDistanceMilesLabel(miles) {
  if (!Number.isFinite(miles)) return "--";
  if (miles < 0.1) return "<0.1 mi";
  if (miles < 10) return `${miles.toFixed(1)} mi`;
  return `${Math.round(miles)} mi`;
}

function distanceBetweenCoordsMeters(from, to) {
  if (!from || !to) return null;
  const lat1 = (from.latitude * Math.PI) / 180;
  const lat2 = (to.latitude * Math.PI) / 180;
  const deltaLat = ((to.latitude - from.latitude) * Math.PI) / 180;
  const deltaLng = ((to.longitude - from.longitude) * Math.PI) / 180;
  const a =
    Math.sin(deltaLat / 2) * Math.sin(deltaLat / 2) +
    Math.cos(lat1) *
      Math.cos(lat2) *
      Math.sin(deltaLng / 2) *
      Math.sin(deltaLng / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return 6371000 * c;
}

function formatDistanceMetersLabel(meters) {
  if (!Number.isFinite(meters)) return "--";
  const miles = meters / 1609.34;
  return formatDistanceMilesLabel(miles);
}

function resolveBusinessCoordinateForDistance(business) {
  if (!business || business.hasCoordinates === false) return null;
  const latitude = Number(
    business.coordinate?.latitude ?? business.latitude ?? business.lat,
  );
  const longitude = Number(
    business.coordinate?.longitude ?? business.longitude ?? business.lng,
  );
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
    return null;
  }
  if (latitude === 0 && longitude === 0) return null;
  if (business.fallbackCoordinate) {
    const deltaLat = Math.abs(latitude - business.fallbackCoordinate.latitude);
    const deltaLng = Math.abs(longitude - business.fallbackCoordinate.longitude);
    if (deltaLat < 0.0001 && deltaLng < 0.0001) return null;
  }
  if (business.address) {
    const deltaLatDefault = Math.abs(latitude - MAP_REGION.latitude);
    const deltaLngDefault = Math.abs(longitude - MAP_REGION.longitude);
    if (deltaLatDefault < 0.001 && deltaLngDefault < 0.001) {
      return null;
    }
  }
  return { latitude, longitude };
}

function parseTimestampMs(value) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  const ms = new Date(value || "").getTime();
  return Number.isFinite(ms) ? ms : null;
}

function normalizeTagFilterValue(value) {
  return String(value || "")
    .toLowerCase()
    .trim()
    .replace(/[_\s]+/g, "-");
}

function tagFilterKeyFromLabel(tagLabel) {
  return `tag:${normalizeTagFilterValue(tagLabel)}`;
}

const readAnimatedValueNow = async (animatedValue, fallback = 0) => {
  try {
    return await new Promise((resolve) => {
      animatedValue.stopAnimation((value) => {
        const numeric = Number(value);
        resolve(Number.isFinite(numeric) ? numeric : fallback);
      });
    });
  } catch (_error) {
    return fallback;
  }
};

function OfferCard({ item, onPress, selected }) {
  const category = getCategoryConfig(item.categoryKey);
  const discoverCategoryLabel = getDiscoverHomeCategoryLabel(
    item?.categoryKey || item?.business?.categoryKey,
  );
  const cashbackRateBps = resolveDisplayedBusinessDefaultCashbackRateBps(
    item?.business || item,
  );
  const cashbackLabel =
    formatPercentOnlyLabel(cashbackRateBps / 100) || null;
  const businessName = String(item?.name || item?.business?.name || "Business").trim();
  const isServiceAreaBusiness = Boolean(
    item?.isServiceAreaBusiness || item?.business?.isServiceAreaBusiness,
  );
  const distanceLabelRaw = String(item?.distanceLabel || item?.distance || "")
    .trim()
    .replace(/\s+/g, " ");
  const distanceMilesNumeric = Number(item?.distanceMiles);
  const distanceMilesFromLabel = parseDistanceLabelMiles(distanceLabelRaw);
  const resolvedDistanceMiles = Number.isFinite(distanceMilesNumeric)
    ? distanceMilesNumeric
    : distanceMilesFromLabel;
  const distanceLabel =
    Number.isFinite(resolvedDistanceMiles)
      ? formatDistanceMilesLabel(resolvedDistanceMiles)
      : "--";
  const hoursValue = item.hours || item.business?.hours || "";
  const fallbackIsOpen =
    typeof item?.isOpen === "boolean"
      ? item.isOpen
      : typeof item?.business?.isOpen === "boolean"
        ? item.business.isOpen
        : null;
  const hoursStatus = getBusinessHoursStatus(hoursValue, fallbackIsOpen);
  const isOpen = hoursStatus.isOpen;
  const statusText = hoursStatus.statusText;
  const statusVariant = hoursStatus.statusVariant;
  const closedOverlayText = hoursStatus.closedOverlayText;
  return (
    <View style={styles.cardShell}>
      <TouchableOpacity
        style={[
          styles.liveEditorialStackCard,
          selected && styles.liveEditorialStackCardSelected,
        ]}
        onPress={onPress}
        activeOpacity={0.85}
      >
        <View style={styles.liveEditorialStackMedia}>
          {item.imageUrl ? (
            <Image
              source={{ uri: item.imageUrl }}
              style={styles.liveEditorialStackMediaImage}
              resizeMode="cover"
              onError={(event) => {
                console.warn("Wello offer image load failed:", {
                  uri: item.imageUrl,
                  error: event.nativeEvent?.error,
                });
              }}
            />
          ) : (
            <View style={styles.liveEditorialStackMediaFallback}>
              <Ionicons
                name="image-outline"
                size={20}
                color="rgba(255,255,255,0.45)"
              />
            </View>
          )}
          <LinearGradient
            colors={["rgba(15, 23, 42, 0.04)", "rgba(15, 23, 42, 0.64)"]}
            start={{ x: 0.5, y: 0 }}
            end={{ x: 0.5, y: 1 }}
            style={styles.liveEditorialStackShade}
          />
          {!isOpen ? (
            <View style={styles.liveEditorialStackClosedOverlay}>
              <View style={styles.liveEditorialStackClosedPill}>
                <Text style={styles.liveEditorialStackClosedText}>
                  {closedOverlayText}
                </Text>
              </View>
            </View>
          ) : null}
          <View style={styles.liveEditorialStackTopRow}>
            <View
              style={[
                styles.liveEditorialStackOpenPill,
                statusVariant === "closing"
                  ? styles.liveEditorialStackOpenPillClosing
                  : statusVariant === "open"
                    ? styles.liveEditorialStackOpenPillOpen
                    : styles.liveEditorialStackOpenPillClosed,
              ]}
            >
              <Text style={styles.liveEditorialStackOpenText}>{statusText}</Text>
            </View>
            <View style={styles.liveEditorialStackCategoryPill}>
              <Text
                style={styles.liveEditorialStackCategoryText}
                numberOfLines={1}
                ellipsizeMode="tail"
              >
                {discoverCategoryLabel || category.display}
              </Text>
            </View>
          </View>
          <View style={styles.liveEditorialStackHeadlineWrap}>
            <Text style={styles.liveEditorialStackName} numberOfLines={1}>
              {businessName}
            </Text>
            {!isServiceAreaBusiness ? (
              <View style={styles.liveEditorialStackHeadlineMetaRow}>
                <Ionicons
                  name="location-outline"
                  size={13}
                  color="rgba(255,255,255,0.9)"
                />
                <Text style={styles.liveEditorialStackHeadlineMeta} numberOfLines={1}>
                  {distanceLabel}
                </Text>
              </View>
            ) : null}
            {cashbackLabel ? (
              <View style={styles.liveEditorialStackBusinessCashbackPill}>
                <Text style={styles.liveEditorialStackBusinessCashbackText}>
                  {cashbackLabel} cashback
                </Text>
              </View>
            ) : null}
          </View>
        </View>
      </TouchableOpacity>
    </View>
  );
}

