  const refreshLiveData = useCallback(
    async ({ silent, force } = {}) => {
      if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return;
      if (liveSyncRef.current.inFlight) return;
      liveSyncRef.current.inFlight = true;
      try {
        if (isSignedIn) {
          const stillExists = await ensureSignedInUserStillExists();
          if (!stillExists) return;
        }
        await refreshAll({ silent: true, force: Boolean(force) });
        if (isSignedIn) {
          await Promise.all([
            loadRedemptions({ silent: true }),
            loadUserReviews({ silent: true }),
            loadCashbackBalance({ silent: true }),
          ]);
        }
        const targetBusinessId = resolvedOwnerBusiness?.id || ownerBusinessId;
        if (isOwner && targetBusinessId) {
          await Promise.all([
            loadOwnerAnalytics(targetBusinessId, { silent: true }),
            loadBillingMetrics(targetBusinessId, { silent: true }),
            loadBusinessReceipts(targetBusinessId, { silent: true }),
            loadBusinessReceiptReports(targetBusinessId, { silent: true }),
            loadBusinessRedemptions(targetBusinessId, { silent: true }),
            loadOwnerOffers(targetBusinessId, { silent: true }),
          ]);
        }
      } finally {
        liveSyncRef.current.inFlight = false;
      }
    },
    [
      refreshAll,
      isSignedIn,
      ensureSignedInUserStillExists,
      isOwner,
      resolvedOwnerBusiness?.id,
      ownerBusinessId,
      loadRedemptions,
      loadUserReviews,
      loadCashbackBalance,
      loadOwnerAnalytics,
      loadBillingMetrics,
      loadBusinessReceipts,
      loadBusinessReceiptReports,
      loadBusinessRedemptions,
      loadOwnerOffers,
    ],
  );

  const scheduleLiveRefresh = useCallback(() => {
    if (liveSyncRef.current.debounce) return;
    liveSyncRef.current.debounce = setTimeout(() => {
      liveSyncRef.current.debounce = null;
      refreshLiveData({ silent: true });
    }, LIVE_DEBOUNCE_MS);
  }, [refreshLiveData]);

  useEffect(() => {
    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !supabase) return;
    if (liveSyncRef.current.channel) {
      liveSyncRef.current.channel.unsubscribe();
      liveSyncRef.current.channel = null;
    }
    const channel = supabase.channel("wello-live");
    const handleChange = () => scheduleLiveRefresh();
    channel.on(
      "postgres_changes",
      { event: "*", schema: "public", table: "businesses" },
      handleChange,
    );
    channel.on(
      "postgres_changes",
      { event: "*", schema: "public", table: "offers" },
      handleChange,
    );
    channel.on(
      "postgres_changes",
      { event: "*", schema: "public", table: "reviews" },
      handleChange,
    );
    if (authUserId) {
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "redemptions",
          filter: `scanned_by=eq.${authUserId}`,
        },
        handleChange,
      );
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "receipt_uploads",
          filter: `user_id=eq.${authUserId}`,
        },
        handleChange,
      );
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "cashback_events",
          filter: `user_id=eq.${authUserId}`,
        },
        handleChange,
      );
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "purchase_verifications",
          filter: `user_id=eq.${authUserId}`,
        },
        handleChange,
      );
    }
    const targetBusinessId = resolvedOwnerBusiness?.id || ownerBusinessId;
    if (targetBusinessId) {
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "receipt_uploads",
          filter: `business_id=eq.${targetBusinessId}`,
        },
        handleChange,
      );
      channel.on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "commission_events",
          filter: `business_id=eq.${targetBusinessId}`,
        },
        handleChange,
      );
    }
    channel.subscribe((status) => {
      if (status === "SUBSCRIBED") {
        scheduleLiveRefresh();
      }
    });
    liveSyncRef.current.channel = channel;
    return () => {
      channel.unsubscribe();
      if (liveSyncRef.current.channel === channel) {
        liveSyncRef.current.channel = null;
      }
    };
  }, [
    authUserId,
    resolvedOwnerBusiness?.id,
    ownerBusinessId,
    scheduleLiveRefresh,
  ]);

  useEffect(() => {
    if (!SUPABASE_URL || !SUPABASE_ANON_KEY) return;
    if (liveSyncRef.current.interval) {
      clearInterval(liveSyncRef.current.interval);
    }
    liveSyncRef.current.interval = setInterval(() => {
      if (AppState.currentState !== "active") return;
      refreshLiveData({ silent: true });
    }, LIVE_POLL_MS);
    return () => {
      if (liveSyncRef.current.interval) {
        clearInterval(liveSyncRef.current.interval);
        liveSyncRef.current.interval = null;
      }
    };
  }, [refreshLiveData]);

  useEffect(() => {
    const subscription = AppState.addEventListener("change", (state) => {
      if (state === "active") {
        refreshLiveData({ silent: true, force: true });
      }
    });
    return () => subscription.remove();
  }, [refreshLiveData]);

  const loadBusinessReviews = useCallback(
    async (businessId, { silent } = {}) => {
      if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
        setBusinessDetailStatus({
          loading: false,
          error: "Supabase is not configured for reviews yet.",
        });
        return;
      }
      if (!businessId) {
        setBusinessDetailReviews([]);
        setBusinessDetailStatus({ loading: false, error: null });
        return;
      }
      if (!silent) {
        setBusinessDetailStatus({ loading: true, error: null });
      }
      const { data, error } = await supabase
        .from("reviews")
        .select(
          "id, business_id, redemption_id, offer_id, rating, review_text, created_at",
        )
        .eq("business_id", businessId)
        .order("created_at", { ascending: false });
      if (error) {
        if (!silent) {
          setBusinessDetailStatus({
            loading: false,
            error: error.message || "Unable to load reviews.",
          });
        }
        return;
      }
      const mapped = (data || []).map(mapSupabaseReview);
      const averageRating = computeAverageRating(mapped);
      setBusinessDetailReviews(mapped);
      setBusinesses((prev) =>
        prev.map((business) =>
          business.id === businessId
            ? { ...business, rating: averageRating }
            : business,
        ),
      );
      setBusinessDetail((prev) =>
        prev && prev.id === businessId
          ? { ...prev, rating: averageRating }
          : prev,
      );
      if (!silent) {
        setBusinessDetailStatus({ loading: false, error: null });
      }
    },
    [],
  );

  const loadOwnerBusinessReviews = useCallback(
    async ({ silent } = {}) => {
      const businessList = Array.isArray(memberBusinesses) ? memberBusinesses : [];
      const businessIds = businessList
        .map((business) => String(business?.id || "").trim())
        .filter(Boolean);

      if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
        setOwnerReviewsStatus({
          loading: false,
          error: "Supabase is not configured for reviews yet.",
        });
        setOwnerReviewGroups([]);
        return;
      }

      if (!businessIds.length) {
        setOwnerReviewGroups([]);
        setOwnerReviewsStatus({ loading: false, error: null });
        return;
      }

      if (!silent) {
        setOwnerReviewsStatus({ loading: true, error: null });
      }

      const { data, error } = await supabase
        .from("reviews")
        .select("id, business_id, user_id, rating, review_text, created_at")
        .in("business_id", businessIds)
        .order("created_at", { ascending: false });

      if (error) {
        if (!silent) {
          setOwnerReviewsStatus({
            loading: false,
            error: error.message || "Unable to load reviews.",
          });
        }
        return;
      }

      const rows = Array.isArray(data) ? data : [];
      const reviewerIds = Array.from(
        new Set(
          rows
            .map((row) => String(row?.user_id || "").trim())
            .filter(Boolean),
        ),
      );

      const reviewerNames = new Map();
      if (reviewerIds.length) {
        const { data: profilesData } = await supabase
          .from("profiles")
          .select("id, full_name")
          .in("id", reviewerIds);
        (profilesData || []).forEach((profile) => {
          const fullName = String(profile?.full_name || "").trim();
          if (!profile?.id) return;
          reviewerNames.set(
            String(profile.id),
            fullName ? fullName.split(/\s+/)[0] : "Anonymous",
          );
        });
      }

      const reviewsByBusiness = new Map();
      rows.forEach((row) => {
        const businessId = String(row?.business_id || "").trim();
        if (!businessId) return;
        const list = reviewsByBusiness.get(businessId) || [];
        list.push({
          id: String(row.id || `${businessId}-${list.length}`),
          businessId,
          rating: Math.max(0, Math.min(5, Number(row?.rating) || 0)),
          reviewText: String(row?.review_text || "").trim(),
          createdAt: row?.created_at ? new Date(row.created_at).getTime() : Date.now(),
          reviewDate: row?.created_at
            ? new Date(row.created_at).toLocaleDateString()
            : "",
          reviewerName:
            reviewerNames.get(String(row?.user_id || "").trim()) || "Anonymous",
        });
        reviewsByBusiness.set(businessId, list);
      });

      setOwnerReviewGroups(
        businessList.map((business) => ({
          businessId: business.id,
          businessName: business.name || "Business",
          reviews: reviewsByBusiness.get(String(business.id || "").trim()) || [],
        })),
      );
      if (!silent) {
        setOwnerReviewsStatus({ loading: false, error: null });
      }
    },
    [memberBusinesses],
  );

  useEffect(() => {
    if (!reviewsPageOpen || !isOwner) return;
    void loadOwnerBusinessReviews({ silent: false });
  }, [isOwner, loadOwnerBusinessReviews, reviewsPageOpen]);

