  const handleCreateBusinessProfile = async () => {
    if (!authUserId) {
      setCreateBusinessError("Sign in to create your business profile.");
      return;
    }
    if (!createBusinessForm.name.trim() || !createBusinessForm.address.trim()) {
      setCreateBusinessError("Business name and address are required.");
      return;
    }
    if (!createBusinessForm.phone.trim()) {
      setCreateBusinessError("Phone number is required.");
      return;
    }
    if (!hasValidBusinessHoursSchedule(createHoursSchedule)) {
      setCreateBusinessError("Operating hours are required.");
      return;
    }
    const categorySelection = resolveSelectedCategory(
      createBusinessForm.categoryKey,
      "",
    );
    if (!categorySelection.ok) {
      setCreateBusinessError(categorySelection.error);
      return;
    }
    const businessSpecialty = String(
      createBusinessForm.categoryCustomLabel || "",
    ).trim();
    if (!businessSpecialty || businessSpecialty === "Other") {
      setCreateBusinessError("Select a specialty or describe what your business does.");
      return;
    }
    const profileDescription = String(
      createBusinessForm.description || "",
    ).trim();
    if (!profileDescription) {
      setCreateBusinessError("Tell customers why they should hire your business.");
      return;
    }
    const selectedCommissionRateCents = 150;
    if (!ensureSupabaseReady(setCreateBusinessError)) return;
    setCreateBusinessBusy(true);
    setCreateBusinessError(null);
    try {
      const offerHonorAcceptedAt = new Date().toISOString();
      const hoursValue = formatBusinessHoursScheduleForStorage(
        createHoursSchedule,
      );
      let createCoords = createBusinessForm.addressCoords;
      if (!createCoords && createBusinessForm.address.trim()) {
        createCoords = await geocodeAddress(
          [
            createBusinessForm.address.trim(),
            createBusinessForm.city.trim(),
            createBusinessForm.state.trim(),
            createBusinessForm.postalCode.trim(),
          ]
            .filter(Boolean)
            .join(", "),
        );
      }
      if (!createCoords) {
        setCreateBusinessBusy(false);
        setCreateBusinessError(
          "Select a valid address so we can place your business on the map.",
        );
        return;
      }
      const usesPrivateServiceAddress =
        createBusinessForm.locationMode === "travel";
      const isShopAndMobileBusiness =
        createBusinessForm.locationMode === "both";
      const publicAddress = usesPrivateServiceAddress
        ? [createBusinessForm.city.trim(), createBusinessForm.state.trim()]
            .filter(Boolean)
            .join(", ") || "Service-area business"
        : createBusinessForm.address.trim();
      let nearestCreateRoadCoordinate = null;
      if (usesPrivateServiceAddress) {
        try {
          nearestCreateRoadCoordinate = await fetchNearestRoadCoordinate(createCoords);
        } catch (error) {
          console.warn("Wello nearest-road lookup failed:", error?.message || error);
        }
      }
      const publicMapCoords =
        usesPrivateServiceAddress && createCoords
          ? nearestCreateRoadCoordinate || createPrivacySafeServiceCoordinate(createCoords)
          : createCoords;
      const { data, error } = await supabase
        .from("businesses")
        .insert({
          owner_id: authUserId,
          name: createBusinessForm.name.trim(),
          address: publicAddress,
          city: createBusinessForm.city.trim() || null,
          state: createBusinessForm.state.trim() || null,
          postal_code: usesPrivateServiceAddress
            ? null
            : createBusinessForm.postalCode.trim() || null,
          phone: createBusinessForm.phone.trim(),
          category_key: categorySelection.categoryKey,
          category_label: categorySelection.categoryLabel,
          offer_highlight: profileDescription,
          commission_rate_cents: selectedCommissionRateCents,
          default_cashback_rate_bps:
            deriveDefaultCashbackRateBpsFromCommission(
              selectedCommissionRateCents,
            ),
          hours: hoursValue,
          tags: Array.from(
            new Set([
              ...normalizeTagsInput(createBusinessForm.tags),
              businessSpecialty.replace(/^Other:\s*/i, "").trim(),
              ...(usesPrivateServiceAddress
                ? ["__wello_service_area__"]
                : []),
              ...(isShopAndMobileBusiness
                ? ["__wello_shop_and_mobile__"]
                : []),
            ].filter(Boolean)),
          ),
          merchant_descriptor_aliases: normalizeMerchantDescriptorAliasesInput(
            createBusinessForm.merchantDescriptorAliases,
          ),
          approval_status: "pending",
          status: "active",
          is_open: true,
          latitude: publicMapCoords?.latitude ?? null,
          longitude: publicMapCoords?.longitude ?? null,
          offer_honor_policy_accepted: true,
          offer_honor_policy_version: OFFER_HONOR_POLICY_VERSION,
          offer_honor_policy_accepted_at: offerHonorAcceptedAt,
          offer_honor_policy_accepted_by: authUserId,
        })
        .select("*")
        .maybeSingle();
      if (error || !data) {
        setCreateBusinessError(
          error?.message || "Unable to create your business profile.",
        );
        return;
      }
      let createdBusinessRow = data;
      if (createBusinessImage?.uri) {
        const upload = await uploadBusinessImage(createBusinessImage, data.id);
        if (upload.error || !upload.url) {
          setCreateBusinessError(
            upload.error ||
              "Business profile created, but the cover photo could not be uploaded.",
          );
        } else {
          const { data: imageRow, error: imageError } = await supabase
            .from("businesses")
            .update({ image_url: upload.url })
            .eq("id", data.id)
            .select("*")
            .maybeSingle();
          if (imageError || !imageRow) {
            await removeBusinessImageByUrl(upload.url);
            setCreateBusinessError(
              imageError?.message ||
                "Business profile created, but the cover photo could not be saved.",
            );
          } else {
            createdBusinessRow = imageRow;
          }
        }
      }
      const profileEmailValue = profileEmail || authEmail || null;
      await supabase.from("profiles").upsert({
        id: authUserId,
        email: profileEmailValue,
        full_name: profileName || null,
        phone: createBusinessForm.phone.trim() || null,
        company: createBusinessForm.name.trim() || null,
      });
      const mapped = mapSupabaseBusiness(createdBusinessRow, 0);
      setBusinesses((prev) => [mapped, ...prev]);
      setOwnerBusinessId(mapped.id);
      setPreferredManagedBusinessId(mapped.id);
      setCreateBusinessPageOpen(false);
      addBusinessReturnBusinessIdRef.current = null;
      await activeBusinessControlsRef.current?.refreshBusinesses?.();
      activeBusinessControlsRef.current?.selectBusinessById?.(mapped.id);
      setCreateBusinessForm({
        name: "",
        description: "",
        hasBusinessLocation: true,
        locationMode: "shop",
        commissionRateCents: 150,
        address: "",
        addressCoords: null,
        city: "",
        state: "",
        postalCode: "",
        categoryKey: DEFAULT_BUSINESS_CATEGORY_KEY,
        categoryCustomLabel: "",
        offer: "",
        phone: "",
        tags: "",
        merchantDescriptorAliases: "",
        imageUrl: "",
      });
      setCreateBusinessImage(null);
      setCreateBusinessImageStatus({ uploading: false, error: null });
      setCreateHoursSchedule(createDefaultBusinessHoursSchedule());
      setCreateHoursDays(DEFAULT_OPERATING_DAYS);
      setCreateHoursStart("");
      setCreateHoursEnd("");
      setCreateHoursStartMeridiem("AM");
      setCreateHoursEndMeridiem("PM");
      setCreateBusinessCategoryMenuOpen(false);
      setCreateBusinessAuthorizedChecked(false);
      setCreateBusinessHonorOffersChecked(false);
    } finally {
      setCreateBusinessBusy(false);
    }
  };

